function sha256(text) {
  return createHash('sha256').update(text).digest('hex');
}

function stateFile(root, name) {
  return join(root, STATE_DIR, name);
}

function readStateJson(root, name) {
  try {
    const parsed = JSON.parse(readFileSync(stateFile(root, name), 'utf-8'));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function writeStateJson(root, name, data) {
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(stateFile(root, name), `${JSON.stringify(data, null, 2)}\n`);
}

export function projectRootFor(startDir) {
  return findProjectRoot(startDir) ?? resolve(startDir);
}

// ===========================================================================
// Owner-facing words. Every string a business owner reads lives here, so the
// jargon test can scan all of it.
// ===========================================================================

const q = (title) => `“${title}”`;

// canPhrase — a part's title as "you can ..." ("Delete a contact" -> "you can
// delete a contact"), or "“<title>” works" when the title does not start with
// something a person does.
const TITLE_VERBS = new Set(('add create make new delete remove edit update change rename find search look sign log ' +
  'view see open book cancel reschedule pay send upload download export import print share invite assign approve ' +
  'reject submit filter sort list track mark complete finish close reopen archive restore save set reset schedule ' +
  'request reply comment rate review register join leave check confirm choose select pick move copy attach browse ' +
  'read write get receive manage turn switch enable disable connect report email message call order buy sell refund ' +
  'invoice charge start stop pause resume lock unlock upgrade downgrade subscribe unsubscribe follow unfollow like ' +
  'tag group merge split duplicate fill enter type scan record note plan reserve claim redeem download use go visit ' +
  'reach return accept decline transfer withdraw deposit verify reorder rank vote post publish unpublish hide show ' +
  'collect sync clear undo').split(' '));
const PERSON_CAN = /^(?:the |a |an |any )?(?:users?|owners?|customers?|visitors?|admins?|staff(?: members?)?|clients?|members?|guests?|people|person|someone|anyone|managers?|employees?|patients?|students?|teachers?) can (.+)$/i;

export function canPhrase(title) {
  const t = String(title || '').trim().replace(/[.!]+$/, '');
  if (!t) return 'this part works';
  const person = PERSON_CAN.exec(t);
  if (person) return `you can ${person[1]}`;
  const first = t.split(/\s+/)[0];
  if (TITLE_VERBS.has(first.toLowerCase()) && !/^[A-Z]{2,}$/.test(first)) return `you can ${lowerFirst(t)}`;
  return `${q(t)} works`;
}

// toYou — the scenario's "they" (the person using the app) as "you", for the
// owner reading it. The stored sentence keeps the scenario's own words.
export function toYou(sentence) {
  return String(sentence || '').replace(/\b([Tt])hey('re|'ve|'ll|'d)?\b/g, (_, t, rest = '') => `${t === 'T' ? 'Y' : 'y'}ou${rest}`);
}

// needsHelpWords — why a part could not be checked and what the owner can do.
function needsHelpWords(needs) {
  const n = String(needs || '').trim().replace(/\.$/, '');
  if (/^a test copy of your app\b/i.test(n)) {
    return { why: 'it needs a test copy of your app, made with made-up information', act: 'sign in to Piezas so your AI tool can make one' };
  }
  if (/could not be reached/i.test(n)) {
    return { why: 'Piezas could not be reached', act: 'check the internet connection and have your AI tool try again' };
  }
  const account = /^a test account for (.+)$/i.exec(n);
  if (account) return { why: `it needs a test account for ${account[1]}`, act: 'give your AI tool a test account' };
  if (/\btest\b.*\baccounts?\b/i.test(n)) return { why: `it needs ${n}`, act: 'give your AI tool a test account' };
  if (n) return { why: `it needs ${n}`, act: 'give your AI tool what it needs' };
  return { why: 'it needs something only you can give', act: 'give your AI tool what it needs' };
}

