// Words an owner must never see. Extends the eval check (evals/adherence.py
// JARGON) with the testing words this gate could leak.
export const OWNER_JARGON = new RegExp(
  [
    String.raw`\b(?:recorded|assertions?|specs?|spec file|playwright|attestations?|fixtures?|seed(?:ed|ing|s)?|exit code|stack trace|CI|flaky|hash(?:es)?|fingerprints?|scenarios?|JSON|npx|phase|gate|manifest|locators?|selectors?|baseline|stubs?|repo|env|PZ0\d\d|SPEC0\d|[RS]-\d{3}|state\.json)\b`,
    String.raw`(?<![\w.])\.piezas\b(?!\.ai)`,
    String.raw`(?:^|\s)--[a-z]`,
    String.raw`\b[\w-]+\/[\w./-]+\.(?:ts|tsx|js|mjs|json|md)\b`,
  ].join('|'),
  'i',
);

export function joinWords(items) {
  const list = items.filter(Boolean);
  if (list.length <= 1) return list.join('');
  if (list.length === 2) return `${list[0]} and ${list[1]}`;
  return `${list.slice(0, -1).join(', ')} and ${list[list.length - 1]}`;
}

// ===========================================================================
// Scenarios, with their words
// ===========================================================================

export const STEP_LINE = /^\s*(?:[-*]\s*)?\**\s*(Given|When|Then|And|But)\b\**\s*(.*)$/i;
export const NEEDS_LINE = /^\s*(?:[-*]\s*)?\**\s*needs\s*\**\s*:\s*(.+)$/i;
const SCENARIO_HEADING_LINE = /^###\s*\**\s*(S-\d+)\s*\**\s*:\s*(.*)$/;

// parseScenarios — every "### S-nnn: title" block under "## Acceptance
// Scenarios", with its Given/When/Then (And/But continue the step above).
export function parseScenarios(text) {
  const lines = blankComments(String(text || '')).split(/\r?\n/);
  const section = splitSections(lines).get('acceptance scenarios');
  const scenarios = [];
  for (const line of section?.lines ?? []) {
    const heading = SCENARIO_HEADING_LINE.exec(line.text);
    if (heading) {
      scenarios.push({ id: heading[1], title: heading[2].replace(/\*+/g, '').trim(), steps: [], needs: [] });
      continue;
    }
    const current = scenarios[scenarios.length - 1];
    if (!current) continue;
    const needs = NEEDS_LINE.exec(line.text);
    if (needs) {
      current.needs.push(...needs[1].split(',').map((s) => s.trim()).filter(Boolean));
      continue;
    }
    const step = STEP_LINE.exec(line.text);
    if (!step) continue;
    let kind = step[1].toLowerCase();
    if (kind === 'and' || kind === 'but') kind = current.steps.length ? current.steps[current.steps.length - 1].kind : 'given';
    current.steps.push({ kind, text: step[2].replace(/\*+/g, '').trim() });
  }
  for (const s of scenarios) {
    for (const kind of ['given', 'when', 'then']) {
      s[kind] = s.steps.filter((step) => step.kind === kind).map((step) => step.text);
    }
  }
  return scenarios;
}

export function readScenarios(root) {
  const specPath = join(root, SPEC_FILE);
  if (!existsSync(specPath)) return { exists: false, scenarios: [], text: '' };
  const text = readFileSync(specPath, 'utf-8');
  return { exists: true, scenarios: parseScenarios(text), text };
}

function normalizeWords(text) {
  return String(text).toLowerCase().replace(/[“”"'`]/g, '').replace(/\s+/g, ' ').trim();
}

// scenarioFingerprint — the scenario's own words. A test written against an
// older wording is "out of date", not "broken".
export function scenarioFingerprint(scenario) {
  const body = [normalizeWords(scenario.title), ...scenario.steps.map((s) => `${s.kind} ${normalizeWords(s.text)}`)].join('\n');
  return sha256(body).slice(0, 12);
}

export function specFingerprint(scenarios) {
  return sha256(scenarios.map((s) => `${s.id}\u0000${scenarioFingerprint(s)}`).sort().join('\n'));
}

// Outside services a scenario depends on. The spec interview flags them (and
// may add a "needs:" line); without a test account they cannot be checked, and
// they are shown as "needs your help" at every deploy, never silently skipped.
export const OUTSIDE_SERVICES = [
  // Either order ("Google sign-in", "signs in with their Google account"),
  // "Continue with Google", "Google Workspace account"; never Google Calendar / Drive.
  ['Google sign-in', /\bgoogle\b[^.\n]{0,30}\b(?:sign(?:s|ed|ing)?|log(?:s|ged|ging)?)[- ]?(in|on)\b|\b(?:sign(?:s|ed|ing)?|log(?:s|ged|ging)?)[- ]?(in|on)\b[^.\n]{0,30}\bgoogle\b(?! (calendar|drive|sheets|docs|maps|meet)\b)|\b(continue|sign[- ]up|register) with google\b|\bgoogle (workspace )?(account|sso|login)\b/i],
  ['Microsoft sign-in', /\b(microsoft|azure ad|entra|office 365|microsoft 365|outlook)\b[^.\n]{0,30}\b(?:sign(?:s|ed|ing)?|log(?:s|ged|ging)?)[- ]?(in|on)\b|\b(?:sign(?:s|ed|ing)?|log(?:s|ged|ging)?)[- ]?(in|on)\b[^.\n]{0,30}\b(microsoft|azure ad|entra|office 365|microsoft 365)\b(?! (teams|calendar|outlook)\b)|\b(continue|sign[- ]up|register) with microsoft\b|\b(microsoft|entra|work or school) account\b/i],
  ['Okta', /\bokta\b/i],
  ['Auth0', /\bauth0\b/i],
  ['Apple sign-in', /\bsign[- ]in with apple\b/i],
  ['company single sign-on', /\b(sso|single sign[- ]on|saml)\b/i],
  ['Stripe', /\bstripe\b/i],
  ['PayPal', /\bpaypal\b/i],
  ['Square', /\bsquare (payment|checkout|pos)\b/i],
  ['card payments', /\b(pays?|paying|payment|checkout|charges?)\b[^.\n]{0,30}\b(card|credit card|online)\b|\bcredit card\b/i],
  ['a real email inbox', /\b(receives?|gets?|opens?|checks?)\b[^.\n]{0,25}\b(e-?mail|inbox)\b|\binbox\b/i],
  ['text messages', /\b(sms|text message|texts? (them|the|a))\b|\btwilio\b/i],
  ['Google Calendar', /\bgoogle calendar\b/i],
  ['Outlook Calendar', /\boutlook calendar\b/i],
  ['Zoom', /\bzoom\b/i],
  ['Slack', /\bslack\b/i],
  ['QuickBooks', /\bquickbooks\b/i],
  ['Xero', /\bxero\b/i],
  ['Salesforce', /\bsalesforce\b/i],
  ['HubSpot', /\bhubspot\b/i],
  ['Mailchimp', /\bmailchimp\b/i],
  ['Shopify', /\bshopify\b/i],
  ['DocuSign', /\bdocusign\b/i],
];

export function outsideServices(scenario) {
  const text = [scenario.title, ...(scenario.steps ?? []).map((s) => s.text)].join('\n');
  const found = OUTSIDE_SERVICES.filter(([, re]) => re.test(text)).map(([name]) => name);
  for (const need of scenario.needs ?? []) if (!found.includes(need)) found.push(need);
  // Specific sign-in providers make the generic one redundant.
  if (found.some((f) => /sign-in|Okta|Auth0/.test(f)) && found.includes('company single sign-on') && !(scenario.needs ?? []).includes('company single sign-on')) {
    return found.filter((f) => f !== 'company single sign-on');
  }
  return found;
}

// ===========================================================================
// Scenario test files and placeholder tests
// ===========================================================================

export function scenarioSlug(title) {
  return String(title || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48)
    .replace(/-+$/g, '') || 'scenario';
}

// scenarioTestFiles — tests/scenarios/S-001.spec.ts or S-001-<anything>.spec.*
export function scenarioTestFiles(root, id) {
  const dir = join(root, SCENARIO_TEST_DIR);
  let names;
  try { names = readdirSync(dir); } catch { return []; }
  return names
    .filter((name) => { const m = SCENARIO_FILE.exec(name); return m && m[1] === id; })
    .sort()
    .map((name) => join(dir, name));
}

export function stubContent(scenario) {
  const steps = scenario.steps.map((s) => `//   ${s.kind.charAt(0).toUpperCase()}${s.kind.slice(1)} ${s.text}`).join('\n');
  return `// piezas-scenario: ${scenario.id} v=${scenarioFingerprint(scenario)}
// ${scenario.id}: ${scenario.title}
${steps}
//
// NOT WRITTEN YET. Replace the test body with the real steps, driven against
// the running app: open the page (page.goto), do what the When line says
// (click, fill, ...), and check what the Then line says is visible
// (await expect(page.getByTestId(...)).toBeVisible() / toHaveText(...)).
// Keep the first line: it tells Piezas which scenario (and which wording of
// it) this test checks. Never skip the test or fake Piezas.
import { test } from '@playwright/test';

test(${JSON.stringify(`${scenario.id}: ${scenario.title}`)}, async () => {
  throw new Error(${JSON.stringify(`${STUB_MARKER}: ${scenario.id} has no test yet`)});
});
`;
}

// ensureScenarioStubs — a failing placeholder for every scenario without a
// test file. Existing files are never touched.
export function ensureScenarioStubs(root, scenarios) {
  const created = [];
  for (const scenario of scenarios) {
    if (scenarioTestFiles(root, scenario.id).length) continue;
    const rel = `${SCENARIO_TEST_DIR}/${scenario.id}-${scenarioSlug(scenario.title)}.spec.ts`;
    const full = join(root, rel);
    if (existsSync(full)) continue;
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, stubContent(scenario));
    created.push(rel);
  }
  return created;
}

// ===========================================================================
// Is this a real test? (static, before running)
// ===========================================================================

export function stripComments(source) {
  return String(source || '').replace(
    /("(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'|`(?:\\.|[^`\\])*`)|\/\*[\s\S]*?\*\/|\/\/[^\n]*/g,
    (match, str) => (str ? str : match.startsWith('/*') ? match.replace(/[^\n]/g, '') : ''),
  );
}

// balanced returns the index just past the bracket matching source[open].
function balanced(source, open) {
  const pairs = { '(': ')', '[': ']', '{': '}' };
  const stack = [];
  let quote = null;
  for (let i = open; i < source.length; i += 1) {
    const ch = source[i];
    if (quote) {
      if (ch === '\\') { i += 1; continue; }
      if (ch === quote) quote = null;
      continue;
    }
    if (ch === '"' || ch === "'" || ch === '`') { quote = ch; continue; }
    if (pairs[ch]) stack.push(pairs[ch]);
    else if (ch === ')' || ch === ']' || ch === '}') {
      if (stack.pop() !== ch) return -1;
      if (stack.length === 0) return i + 1;
    }
  }
  return -1;
}

// expectCalls — every expect(<arg>)[.not].<matcher>(<args>) in the source.
export function expectCalls(source) {
  const calls = [];
  const re = /\bexpect(?:\.soft|\.poll)?\s*\(/g;
  let m;
  while ((m = re.exec(source)) !== null) {
    const open = m.index + m[0].length - 1;
    const close = balanced(source, open);
    if (close < 0) continue;
    const arg = source.slice(open + 1, close - 1).trim();
    const tail = /^\s*((?:\.\s*(?:not|resolves|rejects)\s*)*)\.\s*([A-Za-z_]\w*)\s*\(/.exec(source.slice(close));
    if (!tail) { calls.push({ arg, matcher: '', negated: false, matcherArgs: '', text: source.slice(m.index, close) }); continue; }
    const mOpen = close + tail[0].length - 1;
    const mClose = balanced(source, mOpen);
    const matcherArgs = mClose > 0 ? source.slice(mOpen + 1, mClose - 1).trim() : '';
    calls.push({
      arg,
      matcher: tail[2],
      negated: /\bnot\b/.test(tail[1]),
      matcherArgs,
      text: source.slice(m.index, mClose > 0 ? mClose : close),
    });
    re.lastIndex = mClose > 0 ? mClose : close;
  }
  return calls;
}

export const WEB_FIRST_MATCHERS = new Set([
  'toBeVisible', 'toBeHidden', 'toHaveText', 'toContainText', 'toHaveCount', 'toHaveValue', 'toHaveValues',
  'toHaveURL', 'toHaveTitle', 'toBeChecked', 'toBeEnabled', 'toBeDisabled', 'toHaveAttribute', 'toHaveClass',
  'toBeEditable', 'toBeEmpty', 'toBeFocused', 'toBeAttached', 'toHaveScreenshot', 'toBeInViewport',
  'toHaveAccessibleName', 'toHaveAccessibleDescription', 'toHaveRole', 'toHaveCSS', 'toHaveId', 'toHaveJSProperty',
]);
const ALWAYS_TRUE_ON_OBJECT = new Set(['toBeTruthy', 'toBeDefined', 'toBeInstanceOf']);
const LITERAL = /^(?:true|false|null|undefined|-?\d+(?:\.\d+)?|'[^']*'|"[^"]*"|`[^`$]*`|\[\s*\]|\{\s*\})$/;
const PAGE_EXPR = /\bpage\d*\b|\bgetBy[A-Z]\w*\s*\(|\blocator\s*\(|\$\$?\s*\(|\bframeLocator\s*\(/;
const READS_SCREEN = /\.(textContent|innerText|innerHTML|inputValue|isVisible|isChecked|isEnabled|isHidden|count|getAttribute|allTextContents|allInnerTexts|title|url)\s*\(/;

export const NAVIGATION = /\.\s*goto\s*\(/;
export const INTERACTION = /\.\s*(?:click|dblclick|fill|press|pressSequentially|type|check|uncheck|selectOption|setInputFiles|tap|dragTo|setChecked)\s*\(/;
export const SKIPS = /\b(?:test|it|describe)(?:\.describe)?\.(?:skip|only|fixme|fail)\b/;
const ROUTE_CALL = /\.\s*(?:route|routeFromHAR|routeWebSocket)\s*\(\s*([^,)]+)/g;
const STUBS_PIEZAS = [
  [/\b(?:jest|vi)\.mock\s*\(\s*['"`]@piezas\/sdk/, 'replaces the Piezas SDK with a fake (jest/vi mock)'],
  [/\bmock\.module\s*\(\s*['"`]@piezas\/sdk/, 'replaces the Piezas SDK with a fake (mock.module)'],
  [/from\s+['"`][^'"`]*(?:fake|mock|stub)[-_]?piezas[^'"`]*['"`]|from\s+['"`][^'"`]*piezas[-_]?(?:fake|mock|stub)[^'"`]*['"`]/i, 'imports a fake Piezas'],
  [/process\.env\.PIEZAS_API_URL\s*=(?!=)/, 'points the app at a different Piezas address from inside the test'],
  [/from\s+['"`]msw(?:\/[^'"`]*)?['"`][\s\S]*piezas/i, 'intercepts Piezas requests with msw'],
];

// localHelperSources — the text of local files a test imports (tests/helpers,
// page objects), so navigation and clicks hidden in a helper still count.
export function localHelperSources(testFile, source) {
  const out = [];
  const re = /from\s+['"`](\.{1,2}\/[^'"`]+)['"`]/g;
  let m;
  while ((m = re.exec(source)) !== null) {
    const base = resolve(dirname(testFile), m[1]);
    for (const candidate of [base, `${base}.ts`, `${base}.js`, `${base}.tsx`, `${base}.mjs`, join(base, 'index.ts'), join(base, 'index.js')]) {
      try {
        if (statSync(candidate).isFile()) { out.push(readFileSync(candidate, 'utf-8')); break; }
      } catch { /* try the next */ }
    }
  }
  return out;
}

const NAVIGATION_WHEN = /\b(open|opens|opening|visit|visits|view|views|go(?:es)? to|navigat\w*|look(?:s)? at|load(?:s)?|arriv\w*|land(?:s)? on|browse\w*|see(?:s)? the)\b/i;

// checkScenarioTest — { verdict: 'ok' | 'not-written' | 'fake', reasons } with
// AI-facing reasons. Heuristic on purpose, but each rule names one way a test
// can pass without proving anything.
export function checkScenarioTest(source, options = {}) {
  const raw = String(source || '');
  if (raw.includes(STUB_MARKER)) {
    return { verdict: 'not-written', reasons: ['still the placeholder: write the real steps for this scenario'] };
  }
  const code = stripComments(raw);
  const helpers = (options.helperSources ?? []).map(stripComments).join('\n');
  const all = `${code}\n${helpers}`;
  const reasons = [];

  if (!/\btest\s*\(/.test(code) && !/\bit\s*\(/.test(code)) reasons.push('defines no test()');
  if (SKIPS.test(code)) reasons.push('uses test.skip / test.only / test.fixme / test.fail: a scenario test must always run');
  if (!NAVIGATION.test(all)) reasons.push('never opens the app (no page.goto)');
  const navigationIsTheAction = (options.scenario?.when ?? []).some((w) => NAVIGATION_WHEN.test(w));
  if (!INTERACTION.test(all) && !navigationIsTheAction) {
    reasons.push('never does what the When line says (no click / fill / press / check / selectOption)');
  }

  const locatorVars = new Set();
  for (const vm of code.matchAll(/\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:await\s+)?([^;\n]+)/g)) {
    if (PAGE_EXPR.test(vm[2]) || READS_SCREEN.test(vm[2])) locatorVars.add(vm[1]);
  }
  let visible = 0;
  const trivial = [];
  for (const call of expectCalls(code)) {
    const arg = call.arg.replace(/^await\s+/, '').trim();
    const argIsLiteral = LITERAL.test(arg);
    const sameBothSides = call.matcherArgs && call.matcherArgs.replace(/\s+/g, '') === arg.replace(/\s+/g, '');
    const orTrue = /\|\|\s*true\b|\?\?\s*true\b/.test(arg);
    const touchesScreen = PAGE_EXPR.test(arg) || READS_SCREEN.test(arg) || locatorVars.has(arg.split(/[.([]/)[0]);
    const objectAlwaysTrue = ALWAYS_TRUE_ON_OBJECT.has(call.matcher) && !call.negated && touchesScreen && !READS_SCREEN.test(arg) && !/\bawait\b/.test(call.arg);
    if (argIsLiteral || sameBothSides || orTrue || objectAlwaysTrue) {
      trivial.push(call.text.replace(/\s+/g, ' ').slice(0, 80));
      continue;
    }
    if (touchesScreen || WEB_FIRST_MATCHERS.has(call.matcher)) visible += 1;
  }
  if (trivial.length) reasons.push(`has checks that are always true: ${trivial.join('; ')}`);
  if (visible === 0) reasons.push('checks nothing visible on the page (needs e.g. await expect(page.getByTestId(...)).toBeVisible())');

  for (const rm of code.matchAll(ROUTE_CALL)) {
    const pattern = rm[1].trim();
    if (/piezas/i.test(pattern) || /\/api\//.test(pattern) || /^['"`]\*\*(?:\/\*)?['"`]$/.test(pattern) || /^\/\.\*\/[a-z]*$/.test(pattern)) {
      reasons.push(`intercepts the app's requests (${pattern}): scenario tests must reach the real test copy of the app`);
    }
  }
  for (const [re, why] of STUBS_PIEZAS) if (re.test(all)) reasons.push(why);
  if (/catch\s*(?:\([^)]*\))?\s*\{\s*\}/.test(code) || /expect[^;]*\.catch\s*\(/.test(code)) {
    reasons.push('swallows failures (an empty catch): a failing check must fail the test');
  }
  return reasons.length ? { verdict: 'fake', reasons } : { verdict: 'ok', reasons: [] };
}

// ===========================================================================
// The checks a test makes, for "was a check removed or loosened?"
// ===========================================================================

function normalizeCheck(text) {
  return text
    .replace(/^\s*await\s+/, '')
    .replace(/\bawait\s+/g, '')
    .replace(/"([^"\\]*)"/g, "'$1'")
    .replace(/`([^`$\\]*)`/g, "'$1'")
    .replace(/\s+/g, ' ')
    .replace(/\s*([().,[\]{}])\s*/g, '$1')
    .trim();
}

export function extractChecks(source) {
  return expectCalls(stripComments(source)).map((call) => normalizeCheck(call.text)).filter(Boolean);
}

// compareChecks — multiset difference: a reworded or loosened check shows up
// as one removed and one added, which is exactly what needs the owner's OK.
export function compareChecks(baseline, current) {
  const left = new Map();
  for (const c of current) left.set(c, (left.get(c) ?? 0) + 1);
  const removed = [];
  for (const c of baseline) {
    const n = left.get(c) ?? 0;
    if (n > 0) left.set(c, n - 1);
    else removed.push(c);
  }
  const base = new Map();
  for (const c of baseline) base.set(c, (base.get(c) ?? 0) + 1);
  const added = [];
  for (const c of current) {
    const n = base.get(c) ?? 0;
    if (n > 0) base.set(c, n - 1);
    else added.push(c);
  }
  return { removed, added };
}

export function readBaseline(root) {
  const data = readStateJson(root, BASELINE_FILE);
  return { version: 1, scenarios: {}, history: [], ...(data ?? {}) };
}

export function readDecisions(root) {
  const data = readStateJson(root, DECISIONS_FILE);
  return { version: 1, skipped: {}, checkChangeApprovals: [], ...(data ?? {}) };
}

export function writeDecisions(root, data) {
  writeStateJson(root, DECISIONS_FILE, data);
}

export function readCheckChange(root) {
  return readStateJson(root, CHECK_CHANGE_FILE);
}

function checkChangeFingerprint(entries) {
  return sha256(entries.map((e) => `${e.id}\u0000${e.removed.join('\u0001')}`).sort().join('\n')).slice(0, 24);
}

// ===========================================================================
// The code fingerprint the record is bound to
// ===========================================================================
//
// Every file a person or the AI edits to change what the app does: source,
// styles, config, package files AND the tests (editing a test means running it
// again). Not: installed packages, build output, Piezas's own records, agent
// instruction files, private settings, or SPEC.md (it has its own fingerprint).

// Skipped only at the project root: build output, tool folders, Piezas's own
// records. Inside the app (app/coverage/page.tsx, src/build/...) the same
// names are ordinary source and are fingerprinted.
export const FINGERPRINT_SKIP_DIRS = new Set([
  'node_modules', '.git', '.next', '.turbo', 'build', 'coverage', 'dist', 'out', '.piezas', 'test-results',
  'playwright-report', 'blob-report', '.vercel', '.cache', '.claude', '.cursor', '.codex', '.windsurf', '.idea', '.vscode',
]);
// Skipped at any depth: installed packages and version-control data.
export const FINGERPRINT_SKIP_ANY_DEPTH = new Set(['node_modules', '.git']);

function skipDir(name, atRoot) {
  return FINGERPRINT_SKIP_ANY_DEPTH.has(name) || (atRoot && FINGERPRINT_SKIP_DIRS.has(name));
}
export const FINGERPRINT_SKIP_FILES = new Set([
  'piezas.manifest.json', 'CLAUDE.md', 'AGENTS.md', '.cursorrules', '.windsurfrules', '.gitignore', 'SPEC.md',
  '.DS_Store', 'Thumbs.db', 'next-env.d.ts', 'tsconfig.tsbuildinfo',
]);
const FINGERPRINT_MAX_FILES = 20_000;
const FINGERPRINT_MAX_BYTES = 10 << 20;

export function fingerprintFiles(root) {
  const files = [];
  const walk = (dir) => {
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (files.length >= FINGERPRINT_MAX_FILES) return;
      const full = join(dir, e.name);
      if (e.isSymbolicLink()) continue;
      if (e.isDirectory()) {
        if (!skipDir(e.name, dir === root)) walk(full);
      } else if (e.isFile()) {
        if (FINGERPRINT_SKIP_FILES.has(e.name) || e.name === '.env' || e.name.startsWith('.env.') || e.name.endsWith('.log')) continue;
        files.push(full);
      }
    }
  };
  walk(root);
  return files;
}

// currentSource — the code as it is now, for the app this folder belongs to:
// what a pause records it was shown for.
export function currentSource(projectDir) {
  return sourceFingerprint(projectRootFor(projectDir));
}

export function sourceFingerprint(root) {
  const lines = fingerprintFiles(root).map((full) => {
    const rel = toPosix(relative(root, full));
    let digest;
    try {
      const size = statSync(full).size;
      digest = size > FINGERPRINT_MAX_BYTES ? `size:${size}` : sha256(readFileSync(full));
    } catch {
      digest = 'unreadable';
    }
    return `${rel}\u0000${digest}`;
  });
  return sha256(lines.sort().join('\n'));
}

// ===========================================================================
// Reading the runner's report
// ===========================================================================

function errorText(error) {
  if (!error) return '';
  return [error.message, error.value, error.stack].filter((v) => typeof v === 'string').join('\n');
}

// parseTestReport reads Playwright's JSON reporter: the counts (stats, or a
// walk of the specs) and one entry per test with its outcome, error and
// screenshot. Anything that cannot be counted returns null — an uncounted run
// must never become a green record.
export function parseTestReport(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  if (!data || typeof data !== 'object') return null;

  const tests = [];
  const walk = (suite, file) => {
    const suiteFile = suite?.file || file;
    for (const spec of suite?.specs ?? []) {
      const specFile = spec.file || suiteFile || '';
      const runs = Array.isArray(spec.tests) && spec.tests.length ? spec.tests : [null];
      for (const t of runs) {
        const results = Array.isArray(t?.results) ? t.results : [];
        const failedRun = [...results].reverse().find((r) => r && r.status && r.status !== 'passed' && r.status !== 'skipped') ?? null;
        const status = t?.status ?? (spec.ok ? 'expected' : 'unexpected');
        const screenshot = results
          .flatMap((r) => (Array.isArray(r?.attachments) ? r.attachments : []))
          .find((a) => a && a.name === 'screenshot' && typeof a.path === 'string')?.path ?? null;
        tests.push({
          file: specFile,
          title: spec.title ?? '',
          ok: typeof spec.ok === 'boolean' ? spec.ok : status === 'expected' || status === 'flaky',
          status,
          flaky: status === 'flaky',
          skipped: status === 'skipped',
          error: failedRun ? [errorText(failedRun.error), ...(failedRun.errors ?? []).map(errorText)].filter(Boolean).join('\n') : '',
          location: failedRun?.error?.location ?? null,
          screenshot,
        });
      }
    }
    for (const child of suite?.suites ?? []) walk(child, suiteFile);
  };
  for (const suite of data.suites ?? []) walk(suite, suite?.file);
  const errors = (Array.isArray(data.errors) ? data.errors : []).map(errorText).filter(Boolean);

  const stats = data.stats;
  if (stats && (Number.isFinite(stats.expected) || Number.isFinite(stats.unexpected))) {
    return {
      passed: (Number(stats.expected) || 0) + (Number(stats.flaky) || 0),
      failed: Number(stats.unexpected) || 0,
      tests,
      errors,
    };
  }
  const passed = tests.filter((t) => t.ok && !t.skipped).length;
  const failed = tests.filter((t) => !t.ok && !t.skipped).length;
  if (passed + failed === 0 && errors.length === 0) return null;
  return { passed, failed, tests, errors };
}

// ===========================================================================
// One plain sentence per failure, from the scenario's own words
// ===========================================================================

const AUX = {
  is: "isn't", are: "aren't", was: "wasn't", were: "weren't", can: "can't", will: "won't",
  has: "doesn't have", have: "don't have", does: "doesn't", do: "don't", should: "doesn't", must: "doesn't",
};
const VERBS = [
  'appear', 'show', 'disappear', 'display', 'change', 'update', 'move', 'stay', 'see', 'get', 'receive', 'go', 'return',
  'list', 'include', 'contain', 'open', 'close', 'become', 'turn', 'load', 'send', 'save', 'count', 'match', 'reach',
  'redirect', 'land', 'reflect', 'mark', 'remain', 'read', 'say', 'appear', 'vanish', 'drop', 'reset', 'add', 'remove',
  'lose', 'keep', 'confirm', 'notify', 'free', 'block', 'reject', 'accept', 'arrive', 'expire', 'lock', 'unlock', 'sort',
  'order', 'total', 'equal', 'increase', 'decrease', 'clear', 'fill', 'work', 'let', 'allow', 'take', 'find', 'need',
];
function thirdPerson(verb) {
  if (/(s|sh|ch|x|z|o)$/.test(verb)) return `${verb}es`;
  if (/[^aeiou]y$/.test(verb)) return `${verb.slice(0, -1)}ies`;
  return `${verb}s`;
}
const DETERMINERS = new Set(['the', 'a', 'an', 'their', 'his', 'her', 'its', 'each', 'every', 'this', 'that', 'these', 'those', 'your', 'my', 'our', 'all', 'new', 'no', 'any', 'some']);
const VERB_FORMS = new Map();
for (const v of VERBS) { VERB_FORMS.set(v, { base: v, third: false }); VERB_FORMS.set(thirdPerson(v), { base: v, third: true }); }

function lowerFirst(text) {
  return /^(I|I'm|I've)\b/.test(text) || /^[A-Z]{2,}/.test(text) ? text : `${text.charAt(0).toLowerCase()}${text.slice(1)}`;
}

// negateClause — "the contact appears in the list" -> "the contact doesn't
// appear in the list". Returns null when it cannot negate safely.
export function negateClause(clause) {
  const words = String(clause).trim().replace(/\.$/, '').split(/\s+/);
  for (let i = 1; i < words.length; i += 1) {
    const w = words[i].toLowerCase();
    if (AUX[w]) {
      if ((w === 'is' || w === 'are' || w === 'was' || w === 'were' || w === 'can' || w === 'will') && words[i + 1]?.toLowerCase() === 'not') return null;
      return [...words.slice(0, i), AUX[w], ...words.slice(i + 1)].join(' ');
    }
    const form = VERB_FORMS.get(w);
    // Right after "the", "a", "their"... it is a noun ("the order has").
    if (form && DETERMINERS.has(words[i - 1].toLowerCase())) continue;
    if (form) return [...words.slice(0, i), form.third ? "doesn't" : "don't", form.base, ...words.slice(i + 1)].join(' ');
  }
  return null;
}

const ACTION_FAILURE = /\b(?:locator|page)\.(?:click|dblclick|fill|press|pressSequentially|type|check|uncheck|selectOption|setInputFiles|tap|hover|dragTo|waitForSelector)\b|waiting for (?:locator|getBy|selector)/i;
const CHECK_FAILURE = /\bexpect\s*\(|Expected(?: string| pattern| value)?:|toBeVisible|toHaveText|toContainText|toHaveCount|toHaveURL|toHaveValue/;
const APP_NOT_STARTED = /net::ERR_CONNECTION_REFUSED|ECONNREFUSED[^\n]*(?:localhost|127\.0\.0\.1)|webServer|Process from config\.webServer|page\.goto:[^\n]*(?:localhost|127\.0\.0\.1)/i;
const NETWORK_FAILURE = /ENOTFOUND|EAI_AGAIN|ECONNREFUSED|ECONNRESET|ETIMEDOUT|getaddrinfo|fetch failed|ERR_NAME_NOT_RESOLVED|ERR_INTERNET_DISCONNECTED|socket hang up|network (?:is )?unreachable/i;
const PIEZAS_KEY_MISSING = /\b(?:401|unauthori[sz]ed|invalid[_ ]api[_ ]key|missing[_ ]api[_ ]key|PIEZAS_API_KEY)\b/i;

// classifyFailure — 'app' (default), 'outdated' (the scenario's words changed
// since the test was written), or 'couldnt-test' (Piezas or an outside service
// unreachable; not counted as a failure).
export function classifyFailure({ error = '', scenario, header, baselineEntry, hasTestCopy = true, services = [] }) {
  const currentFp = scenario ? scenarioFingerprint(scenario) : null;
  const writtenFor = header?.fp ?? baselineEntry?.scenarioFingerprint ?? null;
  if (currentFp && writtenFor && !currentFp.startsWith(writtenFor) && !writtenFor.startsWith(currentFp)) return 'outdated';
  if (NETWORK_FAILURE.test(error) && !/localhost|127\.0\.0\.1/.test(error)) return 'couldnt-test';
  if (!hasTestCopy && PIEZAS_KEY_MISSING.test(error)) return 'couldnt-test';
  if (services.length && NETWORK_FAILURE.test(error)) return 'couldnt-test';
  return 'app';
}

// plainFailure — one sentence an owner understands, built from the scenario's
// When/Then and what the screen showed.
export function plainFailure(scenario, error = '', kind = 'app') {
  const title = scenario?.title ?? 'This part';
  if (kind === 'outdated') return OWNER_TEXT.outdated(title);
  if (APP_NOT_STARTED.test(error)) return OWNER_TEXT.appDidNotStart(title);
  const when = (scenario?.when ?? []).map(lowerFirst).join(' and ');
  const then = scenario?.then?.[0] ? lowerFirst(scenario.then[0]) : '';
  const isCheck = CHECK_FAILURE.test(error) && !(ACTION_FAILURE.test(error) && !/\bexpect\s*\(/.test(error));
  if (!isCheck && ACTION_FAILURE.test(error)) {
    return when ? OWNER_TEXT.stuck(when) : OWNER_TEXT.stuckNoWhen(title);
  }
  const negated = then ? negateClause(then) : null;
  let sentence;
  if (negated && when) sentence = OWNER_TEXT.afterThen(when, negated);
  else if (negated) sentence = OWNER_TEXT.thenOnly(negated);
  else sentence = OWNER_TEXT.notAsExpected(title);
  const received = /Received(?: string)?:\s*"([^"\n]{1,80})"/.exec(error);
  if (received && !/[<>{}]|\b(?:undefined|null|NaN)\b/.test(received[1]) && received[1].trim()) {
    sentence = `${sentence} ${OWNER_TEXT.screenShows(received[1].trim())}`;
  }
  return sentence.charAt(0).toUpperCase() + sentence.slice(1);
}

// ===========================================================================
// piezas test
// ===========================================================================

function readEnvFileVar(root, name) {
  const file = join(root, '.env');
  if (!existsSync(file)) return undefined;
  const re = new RegExp(`^\\s*(?:export\\s+)?${name}\\s*=\\s*(.*)$`);
  for (const line of readFileSync(file, 'utf-8').split(/\r?\n/)) {
    const m = re.exec(line);
    if (m) return m[1].trim().replace(/^(['"])(.*)\1$/, '$2') || undefined;
  }
  return undefined;
}

export function testKeyFor(root, env = process.env) {
  const fromEnv = typeof env.PIEZAS_TEST_API_KEY === 'string' && env.PIEZAS_TEST_API_KEY.trim();
  return fromEnv || readEnvFileVar(root, 'PIEZAS_TEST_API_KEY') || null;
}

function runCommand(command, cwd, env) {
  let stdout = '';
  let stderr = '';
  try {
    stdout = execSync(command, { cwd, env, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 64 * 1024 * 1024 }) ?? '';
  } catch (error) {
    // A red suite exits non-zero — that is a RESULT, not an error.
    stdout = typeof error?.stdout === 'string' ? error.stdout : error?.stdout?.toString?.() ?? '';
    stderr = typeof error?.stderr === 'string' ? error.stderr : error?.stderr?.toString?.() ?? '';
  }
  return { stdout, stderr };
}

function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}

function scenarioIdOfFile(file) {
  return SCENARIO_FILE.exec(basename(String(file)))?.[1] ?? null;
}

// runTests — `piezas test`. For the whole command, .piezas/test-running.json
// says a run is going: the quality scan waits for it (a long run is often left
// in the background while the AI waits).
export async function runTests(startDir = process.cwd(), options = {}) {
  const root = projectRootFor(startDir);
  let wrote = false;
  try {
    writeStateJson(root, TEST_RUN_FILE, { pid: process.pid, startedAt: new Date().toISOString() });
    wrote = true;
  } catch { /* best effort */ }
  try {
    return await runTestsOnce(startDir, options);
  } finally {
    // Only this run's own file: another run may have started since.
    if (wrote && readStateJson(root, TEST_RUN_FILE)?.pid === process.pid) {
      try { rmSync(stateFile(root, TEST_RUN_FILE), { force: true }); } catch { /* best effort */ }
    }
  }
}

async function runTestsOnce(startDir, options) {
  const env = options.env ?? process.env;
  const root = projectRootFor(startDir);
  const now = options.now ?? Date.now();
  const { exists: specExists, scenarios } = readScenarios(root);

  // The tool adds the Report a problem button itself (server Next apps), before
  // the code is fingerprinted.
  scaffoldReportButton(root, { quiet: true });

  const created = specExists ? ensureScenarioStubs(root, scenarios) : [];
  const decisions = readDecisions(root);
  const baseline = readBaseline(root);
  const testKey = testKeyFor(root, env);
  const sandbox = isSandboxProject(root);

  // 1. Static check of every scenario test.
  const results = new Map();
  const runnable = [];
  for (const scenario of scenarios) {
    const files = scenarioTestFiles(root, scenario.id);
    const services = outsideServices(scenario);
    const entry = { id: scenario.id, title: scenario.title, status: STATUS.notWritten, files: files.map((f) => toPosix(relative(root, f))), reasons: [], services };
    results.set(scenario.id, entry);
    const sources = files.map((f) => ({ file: f, source: readFileSync(f, 'utf-8') }));
    const checks = sources.map(({ file, source }) => ({
      file,
      source,
      ...checkScenarioTest(source, { scenario, helperSources: localHelperSources(file, source) }),
    }));
    const bad = checks.filter((c) => c.verdict !== 'ok');
    if (!checks.length || bad.length) {
      entry.reasons = bad.flatMap((c) => c.reasons.map((r) => `${toPosix(relative(root, c.file))}: ${r}`));
      if (services.length && (!checks.length || bad.every((c) => c.verdict === 'not-written'))) {
        entry.status = STATUS.needsHelp;
        entry.needs = OWNER_TEXT.needsService(services);
        entry.reasons.push(`depends on ${services.join(', ')}: ask the owner for a test account (they set it themselves, never in chat); until then this is "needs your help"`);
      }
      continue;
    }
    const header = sources.map((s) => SCENARIO_HEADER.exec(s.source)).find(Boolean);
    entry.header = header ? { id: header[1], fp: header[2] } : null;
    entry.checks = checks.flatMap((c) => extractChecks(c.source));
    entry.pending = true;
    runnable.push(...checks.map((c) => toPosix(relative(root, c.file))));
  }

  // 2. Run what is real. One automatic retry: pass-on-retry is a pass, marked
  //    unreliable for the AI only.
  const override = typeof env.PIEZAS_TEST_CMD === 'string' ? env.PIEZAS_TEST_CMD.trim() : '';
  const askedExternal = typeof env.PW_BASE_URL === 'string' && env.PW_BASE_URL.trim() !== '';
  const externalServer = askedExternal && env.PIEZAS_TEST_ALLOW_EXTERNAL_SERVER === '1';
  const runWholeSuite = !specExists || scenarios.length === 0;
  let report = null;
  let ran = null;
  let runnerDetail = '';
  if (runnable.length || runWholeSuite) {
    const reportDir = mkdtempSync(join(tmpdir(), 'piezas-test-'));
    const reportPath = join(reportDir, 'report.json');
    ran = override || (runWholeSuite ? DEFAULT_TEST_COMMAND : `${DEFAULT_TEST_COMMAND} ${runnable.map(shellQuote).join(' ')}`);
    const runEnv = {
      ...env,
      // Scenario runs start the app themselves, with the test copy's key. An
      // app that is already running (PW_BASE_URL) may be using the LIVE key,
      // so it is used only on an explicit opt-in.
      PW_BASE_URL: externalServer ? env.PW_BASE_URL : '',
      PLAYWRIGHT_JSON_OUTPUT_NAME: reportPath,
      PIEZAS_TEST_RUN: '1',
      PIEZAS_TEST_FILES: runnable.join('\n'),
      // The app under test talks to the TEST copy, never the live app. With no
      // test copy it gets no key at all: data checks then wait for the owner.
      PIEZAS_API_KEY: testKey ?? '',
      PIEZAS_TEST_API_KEY: testKey ?? '',
      // The owner's own decision about the Report a problem button: the smoke
      // test does not check for a button the owner chose to go without.
      PIEZAS_REPORT_BUTTON_CHECK: reportButtonOwnerOff(root) ? 'off' : (env.PIEZAS_REPORT_BUTTON_CHECK ?? ''),
    };
    // The made-up records first, into the test copy (and only there).
    const seedPath = join(root, 'scripts', 'seed.ts');
    if (testKey && env.PIEZAS_SEED_CMD) runCommand(env.PIEZAS_SEED_CMD, root, runEnv);
    else if (testKey && !override && existsSync(seedPath)) runCommand('npx --yes tsx scripts/seed.ts', root, runEnv);
    const { stdout, stderr } = runCommand(ran, root, runEnv);
    try {
      if (existsSync(reportPath)) report = parseTestReport(readFileSync(reportPath, 'utf-8'));
    } catch { /* unreadable -> stdout */ }
    if (!report) report = parseTestReport(stdout);
    runnerDetail = (stderr || stdout).split('\n').map((l) => l.trim()).filter(Boolean)[0] ?? '';
    try { rmSync(reportDir, { recursive: true, force: true }); } catch { /* best effort */ }

    if (!report) {
      // A run nobody can read is not a green run: record NOTHING. It is one
      // of the AI's attempts, though: after MAX_CHECK_ATTEMPTS the owner is
      // asked (the override never goes away).
      noteCheckAttempt(root);
      return {
        exitCode: 1,
        command: 'test',
        attestation: null,
        json: {
          command: 'test', ok: false, ran, attestation: null, created,
          next: [`the runner produced no readable report${runnerDetail ? ` (${runnerDetail.slice(0, 200)})` : ''}: install the harness (npm install && npx playwright install), then run piezas test again`],
        },
        output: [OWNER_TEXT.couldNotRun],
      };
    }
  }

  // 3. Results per scenario.
  const resultsDir = join(root, STATE_DIR, TEST_RESULTS_DIR);
  mkdirSync(resultsDir, { recursive: true });
  for (const name of readdirSync(resultsDir)) if (/^S-\d+\.png$/.test(name)) rmSync(join(resultsDir, name), { force: true });
  const byScenario = new Map();
  for (const t of report?.tests ?? []) {
    const id = scenarioIdOfFile(t.file);
    if (!id) continue;
    if (!byScenario.has(id)) byScenario.set(id, []);
    byScenario.get(id).push(t);
  }
  const globalError = (report?.errors ?? []).join('\n');
  const pendingChanges = [];
  const nextBaseline = { ...baseline, scenarios: { ...baseline.scenarios } };
  for (const scenario of scenarios) {
    const entry = results.get(scenario.id);
    if (!entry.pending) continue;
    delete entry.pending;
    const tests = (byScenario.get(scenario.id) ?? []).filter((t) => !t.skipped);
    const failed = tests.filter((t) => !t.ok);
    if (!tests.length) {
      if (globalError) {
        entry.status = STATUS.failed;
        entry.kind = classifyFailure({ error: globalError, scenario, header: entry.header, hasTestCopy: Boolean(testKey), services: entry.services });
        entry.error = globalError.slice(0, 2000);
      } else {
        entry.status = STATUS.notWritten;
        entry.reasons.push('no test ran from this file (is there a test() call, and is the file inside the test folder?)');
      }
    } else if (failed.length) {
      const error = failed.map((t) => t.error).join('\n') || globalError;
      entry.status = STATUS.failed;
      entry.kind = classifyFailure({
        error, scenario, header: entry.header, baselineEntry: baseline.scenarios[scenario.id], hasTestCopy: Boolean(testKey), services: entry.services,
      });
      entry.error = error.slice(0, 2000);
      entry.location = failed.find((t) => t.location)?.location ?? null;
      const shot = failed.find((t) => t.screenshot && existsSync(t.screenshot))?.screenshot;
      if (shot) {
        try {
          copyFileSync(shot, join(resultsDir, `${scenario.id}.png`));
          entry.screenshot = `${TEST_RESULTS_REL}/${scenario.id}.png`;
        } catch { /* best effort */ }
      }
    } else {
      entry.status = STATUS.passed;
      if (tests.some((t) => t.flaky)) entry.unreliable = true;
    }

    if (entry.status === STATUS.failed && entry.kind === 'couldnt-test') {
      entry.status = STATUS.needsHelp;
      entry.needs = !testKey && PIEZAS_KEY_MISSING.test(entry.error ?? '') ? OWNER_TEXT.needsTestCopy
        : entry.services.length ? OWNER_TEXT.needsService(entry.services) : OWNER_TEXT.piezasUnreachable.replace(/\.$/, '').toLowerCase();
    } else if (entry.status === STATUS.failed) {
      entry.plain = plainFailure(scenario, entry.error ?? '', entry.kind);
    }

    // Weakened checks need the owner's OK; first passes set the baseline.
    if (entry.status === STATUS.passed) {
      const prior = baseline.scenarios[scenario.id];
      const fp = scenarioFingerprint(scenario);
      if (!prior) {
        nextBaseline.scenarios[scenario.id] = { checks: entry.checks, scenarioFingerprint: fp, files: entry.files, recordedAt: new Date(now).toISOString() };
      } else {
        const { removed, added } = compareChecks(prior.checks ?? [], entry.checks);
        if (removed.length) {
          entry.status = STATUS.changedChecks;
          entry.removedChecks = removed;
          entry.addedChecks = added;
          pendingChanges.push({ id: scenario.id, title: scenario.title, removed, added, current: entry.checks, scenarioFingerprint: fp });
        } else if (added.length || prior.scenarioFingerprint !== fp) {
          nextBaseline.scenarios[scenario.id] = { ...prior, checks: entry.checks, scenarioFingerprint: fp, files: entry.files, updatedAt: new Date(now).toISOString() };
        }
      }
    }
    delete entry.checks;
  }

  // 4. Owner decisions: "skip this one for now" holds until the part passes.
  let decisionsChanged = false;
  for (const entry of results.values()) {
    const skip = decisions.skipped?.[entry.id];
    if (!skip) continue;
    if (entry.status === STATUS.passed) {
      delete decisions.skipped[entry.id];
      decisionsChanged = true;
    } else if (!ALLOWED_STATUSES.has(entry.status)) {
      entry.skippedFrom = entry.status;
      entry.status = STATUS.skipped;
    }
  }
  if (decisionsChanged) writeDecisions(root, decisions);
  writeStateJson(root, BASELINE_FILE, nextBaseline);
  if (pendingChanges.length) {
    const fingerprint = checkChangeFingerprint(pendingChanges);
    const prior = readCheckChange(root);
    writeStateJson(root, CHECK_CHANGE_FILE, {
      fingerprint,
      scenarios: pendingChanges,
      at: new Date(now).toISOString(),
      // Never marked as asked here: this output lands in the AI's tool
      // result, so the owner may never see it. Only the Stop hook marks the
      // question asked, when the AI's final message relays it
      // (markCheckChangeAsked). An earlier mark for the same change is kept;
      // the Stop hook clears it at the end of the turn unless it was relayed.
      ...(prior?.fingerprint === fingerprint && prior.askedAt ? { askedAt: prior.askedAt, askedIds: prior.askedIds ?? [] } : {}),
    });
  } else {
    rmSync(stateFile(root, CHECK_CHANGE_FILE), { force: true });
  }

  // 5. The record, bound to this code and this description, valid a day.
  const list = scenarios.map((s) => results.get(s.id));
  const counts = {
    passed: list.filter((e) => e.status === STATUS.passed).length,
    failed: list.filter((e) => e.status === STATUS.failed).length,
    notWritten: list.filter((e) => e.status === STATUS.notWritten).length,
    needsHelp: list.filter((e) => e.status === STATUS.needsHelp).length,
    skipped: list.filter((e) => e.status === STATUS.skipped).length,
    changedChecks: list.filter((e) => e.status === STATUS.changedChecks).length,
  };
  const rawFailed = runWholeSuite ? (report?.failed ?? 0) : 0;
  const passing = list.every((e) => ALLOWED_STATUSES.has(e.status)) && rawFailed === 0;
  const ranAt = new Date(now).toISOString();
  // The AI's rounds (Spec 1-B): each version of the code that still fails is
  // one round; the same code run again is not. A pass (or a changed app
  // description) starts over. What changed since the last run is the owner's
  // one progress line.
  const prev = readStateJson(root, ATTESTATION_FILE);
  const thisSource = sourceFingerprint(root);
  const thisSpec = specFingerprint(scenarios);
  const fixable = (e) => e.status === STATUS.failed || e.status === STATUS.notWritten;
  let rounds = 0;
  let stuck = 0;
  let progress = null;
  if (!passing && list.some(fixable)) {
    const sameWork = prev && prev.passing === false && prev.specFingerprint === thisSpec && Number.isInteger(prev.rounds) && prev.rounds > 0;
    // The same code run again is not a new round, but a stuck AI must still
    // reach the owner: every STUCK_RERUNS runs of unchanged code count as one.
    const sameSource = sameWork && prev.sourceFingerprint === thisSource;
    stuck = sameSource ? (Number.isInteger(prev.stuck) && prev.stuck > 0 ? prev.stuck : 0) + 1 : 0;
    const stuckRound = stuck >= STUCK_RERUNS;
    if (stuckRound) stuck = 0;
    rounds = sameWork ? prev.rounds + (!sameSource || stuckRound ? 1 : 0) : 1;
    if (sameWork) {
      const before = new Map((prev.scenarios ?? []).map((e) => [e?.id, e?.status]));
      progress = {
        written: list.filter((e) => before.get(e.id) === STATUS.notWritten && e.status !== STATUS.notWritten).length,
        fixed: list.filter((e) => before.get(e.id) === STATUS.failed && e.status === STATUS.passed).length,
      };
    }
  }
  if (passing && decisions.keepTrying) {
    delete decisions.keepTrying;
    writeDecisions(root, decisions);
  }
  const scenarioById = new Map(scenarios.map((sc) => [sc.id, sc]));
  const attestation = {
    version: ATTESTATION_VERSION,
    ranAt,
    validUntil: new Date(now + ATTESTATION_MAX_AGE_MS).toISOString(),
    sourceFingerprint: thisSource,
    specFingerprint: thisSpec,
    passing,
    ...(rounds ? { rounds } : {}),
    ...(stuck ? { stuck } : {}),
    ...(progress ? { progress } : {}),
    // Each part's answer key (partFingerprint), so another reader (the MCP)
    // matches a per-part "deploy anyway" exactly as this CLI does.
    scenarios: list.map((e) => ({
      id: e.id,
      title: e.title,
      status: e.status,
      ...(scenarioById.get(e.id) ? { fp: partFingerprint(scenarioById.get(e.id), e.status) } : {}),
      ...(e.plain ? { plain: e.plain } : {}),
      ...(e.needs ? { needs: e.needs } : {}),
    })),
    passed: runWholeSuite ? (report?.passed ?? 0) : counts.passed,
    failed: runWholeSuite ? rawFailed : counts.failed + counts.notWritten + counts.changedChecks,
    counts,
    acceptedChanges: (nextBaseline.history ?? []).map((h) => ({ id: h.id, reason: h.reason, at: h.at })),
    testCopy: Boolean(testKey),
    ...(externalServer ? { externalServer: true } : {}),
  };
  writeStateJson(root, ATTESTATION_FILE, attestation);

  // 6. What the owner reads; what the AI reads.
  const output = [];
  if (runWholeSuite) {
    output.push(OWNER_TEXT.rawRunHeader(attestation.passed, attestation.failed));
  } else {
    // Counted by group, as at the deploy stop; what went wrong is said for
    // each part that does not work. Every part is in the result for the AI.
    output.push(OWNER_TEXT.runHeader(list.length));
    for (const line of summaryLines(list)) output.push(`  ${line}`);
    for (const e of list) if (e.status === STATUS.failed) output.push(`    ${OWNER_TEXT.checkedFailed(e)}`);
    // Every part by name, so the AI can show the full list (the deploy stop
    // only counts them).
    output.push('', ...partListLines(list).map((l) => `  ${l}`));
  }
  const notReady = list.filter((e) => !ALLOWED_STATUSES.has(e.status)).length + (rawFailed ? 1 : 0);
  output.push('');
  if (passing) output.push(list.some((e) => e.status !== STATUS.passed) ? OWNER_TEXT.readyWithNotes : OWNER_TEXT.ready);
  else output.push(OWNER_TEXT.notReady(notReady || 1));
  const verdictNow = rounds ? testGateVerdict(root, { now }) : null;
  if (rounds) {
    output.push(verdictNow.gaveUp ? OWNER_TEXT.stoppedAfterRounds(verdictNow.round) : OWNER_TEXT.progress({ ...(progress ?? {}), round: Math.min(verdictNow.round + 1, MAX_FIX_ATTEMPTS) }));
  }
  if (externalServer) output.push(OWNER_TEXT.externalServer);
  if (!testKey && !sandbox && list.length) output.push(OWNER_TEXT.noTestCopy);
  if (!testKey && sandbox && list.length) output.push(OWNER_TEXT.testCopySandbox);

  const next = aiNextSteps(list, { testKey, created, sandbox });
  if (askedExternal && !externalServer) {
    next.push('PW_BASE_URL was ignored: piezas test starts the app itself with the test copy\'s key (an already-running app may use the live key). '
      + 'Only for a server you know uses the test copy: set PIEZAS_TEST_ALLOW_EXTERNAL_SERVER=1 as well.');
  }
  if (externalServer) next.push(`ran against the already-running app at ${env.PW_BASE_URL} (PIEZAS_TEST_ALLOW_EXTERNAL_SERVER=1): make sure it uses PIEZAS_TEST_API_KEY, never the live key`);
  return {
    exitCode: passing ? 0 : 1,
    command: 'test',
    attestation,
    json: {
      command: 'test',
      ok: passing,
      ran,
      attestation: ATTESTATION_REL,
      created,
      testCopy: Boolean(testKey),
      externalServer,
      scenarios: list.map((e) => ({ ...e })),
      next,
      maxFixAttempts: MAX_FIX_ATTEMPTS,
      ...(rounds ? { round: verdictNow.round, gaveUp: verdictNow.gaveUp } : {}),
    },
    output,
  };
}

// aiNextSteps — the repair list for the AI (never shown to the owner as is).
export function aiNextSteps(list, { testKey, created = [], sandbox = false } = {}) {
  const next = [];
  if (created.length) next.push(`created failing placeholder tests: ${created.join(', ')} — write each from its scenario, keeping the first "piezas-scenario" line`);
  for (const e of list) {
    if (e.status === STATUS.notWritten) next.push(`${e.id}: write the test (${e.files[0] ?? `${SCENARIO_TEST_DIR}/${e.id}-<slug>.spec.ts`})${e.reasons.length ? ` — rejected: ${e.reasons.join('; ')}` : ''}`);
    if (e.status === STATUS.failed && e.kind === 'outdated') next.push(`${e.id}: the scenario's words changed since the test was written — update the test to the current scenario and its "piezas-scenario" line, then re-run`);
    if (e.status === STATUS.failed && e.kind !== 'outdated') next.push(`${e.id}: fix the app so the scenario works (screenshot: ${e.screenshot ?? 'none'}), re-run; after ${MAX_FIX_ATTEMPTS} failed tries tell the owner: "${e.plain}"`);
    if (e.status === STATUS.changedChecks) next.push(`${e.id}: checks were removed or loosened (${(e.removedChecks ?? []).join(' | ')}). Restore them, or tell the owner in ONE plain sentence what you changed and why, then end your message with this exact line: "${OWNER_TEXT.changedCheck(checkChangeName(e), OWNER_TEXT.changedCheckReply(checkChangeName(e)))}" and wait for their reply (only "${OWNER_TEXT.changedCheckReply(checkChangeName(e))}" counts); only after they say OK run: piezas test --accept-change ${e.id} --reason "<that sentence>"`);
    if (e.status === STATUS.needsHelp) next.push(`${e.id}: needs the owner: ${e.needs}. Ask them in plain words; they set any test account themselves (never in chat)`);
    if (e.unreliable) next.push(`${e.id}: passed only on the automatic retry — likely timing-dependent; make it reliable (wait for the right element) before relying on it`);
  }
  if (!testKey && !sandbox && list.length) next.push('no test copy of the app: run piezas test --setup (needs the owner signed in to Piezas)');
  return next;
}

// ===========================================================================
// Owner-approved changes to how a part is checked
// ===========================================================================

export const AGENT_ACCEPT_CHANGE = /(?:\bpiezas(?:\.mjs)?(?:@[^\s"'/]+)?|@piezas\/cli(?:@[^\s"']+)?|\bindex\.js)["']?\s+(?:--\s+)?test\b[^\n;|&]*--accept-change\b(?:[\s=]+(S-\d+(?:\s*,\s*S-\d+)*))?/;
// checkChangeBlock — why the AI cannot accept a rewritten check itself. It
// carries each part's full line, so an AI that copies it relays a question the
// Stop hook recognises, and names the owner's own terminal as the other way.
export function checkChangeBlock(root, ids = []) {
  const scenarios = (readCheckChange(root)?.scenarios ?? []).filter((s) => !ids.length || ids.includes(s.id));
  const relay = scenarios.length
    ? `, then end your message with ${scenarios.length > 1 ? 'these exact lines' : 'this exact line'}: ${scenarios.map((s) => `"${changedCheckLine(s)}"`).join(' ')}`
    : ', then end your message with the exact line Piezas printed for that part';
  const terminal = scenarios.length
    ? ` The owner can also OK it in their own terminal: ${scenarios.map((s) => `npx piezas test --accept-change ${s.id} --reason "<what changed and why>"`).join(', ')}.`
    : '';
  if (relayAllowed(root)) {
    const ids = scenarios.length ? scenarios.map((s) => s.id).join(', ') : '<part>';
    return `Piezas: only the owner can OK a change to how a part of the app is checked. Tell them in one plain sentence what you changed and why${relay} Then wait for their reply. ` +
      `No Piezas hooks are installed for this project to record it, so relay their exact words: npx piezas test --accept-change ${ids} --reason "<what changed and why>" --owner-reply "<their exact words>" ` +
      '(it counts only when they name the part, as in "yes <part>"; a bare "yes" is not). If they say "keep fixing", restore the original checks instead. Never send them to a terminal for this.';
  }
  return `Piezas: only the owner can OK a change to how a part of the app is checked. Tell them in one plain sentence what you changed and why${relay} Then wait: their reply "yes <part>" is recorded automatically (a bare "yes" is not). Or restore the original checks.${terminal}`;
}

export function checkChangeApproved(root, id) {
  const pending = readCheckChange(root);
  if (!pending?.fingerprint || !pending.scenarios?.some((s) => s.id === id)) return false;
  return readDecisions(root).checkChangeApprovals.some((a) => a.fingerprint === pending.fingerprint && (a.ids ?? []).includes(id));
}

export function recordCheckChangeApproval(root, pending, said, via) {
  const decisions = readDecisions(root);
  decisions.checkChangeApprovals = [
    ...decisions.checkChangeApprovals,
    { fingerprint: pending.fingerprint, ids: pending.scenarios.map((s) => s.id), said: String(said).slice(0, 200), via, at: new Date().toISOString() },
  ];
  writeDecisions(root, decisions);
}

export async function acceptCheckChange(startDir, options = {}) {
  const root = projectRootFor(startDir);
  const id = String(options.id || '').trim();
  const reason = String(options.reason || '').trim();
  const fail = (msg, status) => ({ exitCode: 1, command: 'test', json: { command: 'test --accept-change', ok: false, status, id }, output: [msg] });
  const pending = readCheckChange(root);
  const item = pending?.scenarios?.find((s) => s.id === id);
  if (!item) return fail(`Nothing is waiting for an OK about ${id || 'that part'}. Run the checks again first.`, 'nothing-pending');
  if (!reason) return fail('Say why the check changed, in one plain sentence (--reason "...").', 'reason-required');
  const relayed = typeof options.ownerReply === 'string' ? options.ownerReply.trim() : '';
  if (!checkChangeApproved(root, id) && relayed) {
    // No hooks in this session to record the owner's reply (the connector, the
    // Codex plugin, a project set up through the MCP): the AI relays their
    // exact words, which must OK this part by name ("yes <part>"). While the
    // hooks run, only their record counts (the guard refuses this command).
    if (!relayAllowed(root)) return fail(checkChangeBlock(root, [id]), 'owner-not-asked');
    const reply = OWNER_TEXT.changedCheckReply(checkChangeName(item));
    // Each part by name ("yes Add a contact and Delete a contact" OKs both);
    // never "yes all" / "both", which only a question Piezas saw asked can mean.
    const named = isAllApproval(relayed) ? [] : approvedCheckChanges(relayed, pending.scenarios, pending.scenarios);
    if (!named.some((s) => s.id === id)) {
      return fail(`The owner's words ("${relayed.slice(0, 120)}") do not OK ${q(item.title)} by name. Ask them to reply "${reply}" (or "keep fixing"), then relay exactly what they said.`, 'relay-not-ok');
    }
    recordCheckChangeApproval(root, { ...pending, scenarios: named }, relayed, 'relayed');
  }
  if (!checkChangeApproved(root, id)) {
    const canAsk = !inAiTool(options.env ?? process.env) && (options.promptFn || (options.interactive && process.stdin.isTTY));
    if (!canAsk) return fail(checkChangeBlock(root, [id]), 'owner-not-asked');
    const promptFn = options.promptFn ?? promptViaTerminal;
    log(`  ${OWNER_TEXT.checkChangeQuestion(item.title, reason.replace(/\.$/, ''))}`);
    const answer = String((await promptFn('  Type yes to accept it, or press Enter to keep the original check: ')) ?? '').trim().toLowerCase();
    if (answer !== 'yes' && answer !== 'y') return fail('Kept the original check.', 'owner-declined');
    recordCheckChangeApproval(root, pending, answer, 'terminal');
  }
  const baseline = readBaseline(root);
  const at = new Date().toISOString();
  baseline.scenarios = { ...baseline.scenarios, [id]: { checks: item.current, scenarioFingerprint: item.scenarioFingerprint, recordedAt: at, acceptedChange: true } };
  baseline.history = [...(baseline.history ?? []), { id, reason, removed: item.removed, added: item.added, at }];
  writeStateJson(root, BASELINE_FILE, baseline);
  const rest = pending.scenarios.filter((s) => s.id !== id);
  if (rest.length) writeStateJson(root, CHECK_CHANGE_FILE, { ...pending, scenarios: rest });
  else rmSync(stateFile(root, CHECK_CHANGE_FILE), { force: true });
  return {
    exitCode: 0,
    command: 'test',
    json: { command: 'test --accept-change', ok: true, id, reason, next: 'run piezas test again' },
    output: [`Accepted the new way ${q(item.title)} is checked. Run the checks again.`],
  };
}

// ===========================================================================
// The deploy stop
// ===========================================================================

export function readTestAttestation(projectDir) {
  const data = readStateJson(projectRootFor(projectDir), ATTESTATION_FILE);
  return data;
}

// testGateVerdict — may this version go live? ok, or why not, with the parts
// named. Applies only to apps whose description has scenarios.
export function testGateVerdict(projectDir, options = {}) {
  const root = projectRootFor(projectDir);
  const now = options.now ?? Date.now();
  const { scenarios } = readScenarios(root);
  if (!scenarios.length) return { ok: true, applicable: false, verdict: 'ok', problems: [], notes: [], fingerprint: null };
  const att = readTestAttestation(root);
  const decisions = readDecisions(root);
  const source = sourceFingerprint(root);
  const byId = new Map((Array.isArray(att?.scenarios) ? att.scenarios : []).map((s) => [s?.id, s]));
  let verdict = 'ok';
  const problems = [];
  const notes = [];
  const passed = [];
  const ranAt = Date.parse(att?.ranAt);
  if (!att || att.version !== ATTESTATION_VERSION || !Array.isArray(att.scenarios) || !Number.isFinite(ranAt)) verdict = 'missing';
  else if (now - ranAt > ATTESTATION_MAX_AGE_MS || ranAt - now > 5 * 60 * 1000) verdict = 'stale';
  else if (att.sourceFingerprint !== source || att.specFingerprint !== specFingerprint(scenarios)) verdict = 'changed';

  for (const s of scenarios) {
    const entry = byId.get(s.id);
    let status = verdict === 'missing' || !entry || !SCENARIO_STATUSES.includes(entry.status) ? STATUS.notWritten : entry.status;
    if (!ALLOWED_STATUSES.has(status) && decisions.skipped?.[s.id]) status = STATUS.skipped;
    const item = { id: s.id, title: s.title, status, fp: partFingerprint(s, status), ...(entry?.plain ? { plain: entry.plain } : {}), ...(entry?.needs ? { needs: entry.needs } : {}) };
    if (ALLOWED_STATUSES.has(status)) {
      if (status !== STATUS.passed) notes.push(item);
      else passed.push(item);
    } else {
      problems.push(item);
    }
  }
  if (verdict === 'ok' && problems.length) verdict = 'not-passing';
  const ok = verdict === 'ok';
  // Keyed on which parts have which result, never on the words shown.
  const fingerprint = ok ? null : sha256([
    'test-gate',
    verdict,
    ...problems.map((p) => `${p.id}\u0000${p.status}`).sort(),
    source,
  ].join('\n')).slice(0, 24);
  // The AI's rounds of fixes (Spec 1-B): counted by `piezas test` per version
  // of the code that still failed; the owner's "keep trying" gives three more.
  const rounds = !ok && verdict === 'not-passing' ? (Number.isInteger(att?.rounds) && att.rounds > 0 ? att.rounds : 1) : 0;
  const from = Number.isInteger(decisions.keepTrying?.from) ? decisions.keepTrying.from : 0;
  const round = Math.max(0, rounds - (from <= rounds ? from : 0));
  const fixable = problems.filter((p) => p.status === STATUS.failed || p.status === STATUS.notWritten);
  const gaveUp = verdict === 'not-passing' && fixable.length > 0 && round >= MAX_FIX_ATTEMPTS;
  const progress = att?.progress && typeof att.progress === 'object' ? att.progress : null;
  // A version with no current check run: after MAX_CHECK_ATTEMPTS real
  // `piezas test` runs that produced nothing readable, the owner is asked. A
  // refused deploy is not an attempt (the AI never ran a check).
  const checkTries = ok || verdict === 'not-passing' ? 0 : checkAttemptsOf(decisions, att);
  return {
    ok, applicable: true, verdict, problems, notes, passed, fingerprint, sourceFingerprint: source,
    ranAt: Number.isFinite(ranAt) ? att.ranAt : null,
    rounds, round, gaveUp, progress, checkTries, checkGaveUp: checkTries >= MAX_CHECK_ATTEMPTS,
  };
}

// The AI's attempts at a version with no current check run, keyed on the last
// run (a new run starts over). Kept with the owner's test decisions, which the
// AI cannot write.
export const MAX_CHECK_ATTEMPTS = 3;
// Runs of unchanged code that count as one round of fixes.
export const STUCK_RERUNS = 2;
const checkAttemptKey = (att) => String(att?.ranAt ?? 'none');
function checkAttemptsOf(decisions, att) {
  const a = decisions?.checkAttempts;
  return a && a.key === checkAttemptKey(att) && Number.isInteger(a.n) && a.n > 0 ? a.n : 0;
}

// testDecisionsSummary — the owner's "keep trying" and the AI's check
// attempts, as the build carries them (the MCP reads them from there).
export function testDecisionsSummary(projectDir) {
  try {
    const d = readDecisions(projectRootFor(projectDir));
    const out = {};
    if (d.keepTrying && typeof d.keepTrying === 'object') out.keepTrying = d.keepTrying;
    if (d.checkAttempts && typeof d.checkAttempts === 'object') out.checkAttempts = d.checkAttempts;
    return Object.keys(out).length ? out : null;
  } catch {
    return null;
  }
}

export function noteCheckAttempt(projectDir) {
  try {
    const root = projectRootFor(projectDir);
    const decisions = readDecisions(root);
    const key = checkAttemptKey(readStateJson(root, ATTESTATION_FILE));
    decisions.checkAttempts = { key, n: checkAttemptsOf(decisions, readStateJson(root, ATTESTATION_FILE)) + 1, at: new Date().toISOString() };
    writeDecisions(root, decisions);
  } catch { /* best effort: the AI keeps its turn */ }
}

export const partItem = (p) => ({ kind: 'part', key: p.id, fp: p.fp ?? '', title: p.title });

// testsPauseItems — what the owner answers for the checks: each part that
// holds the deploy up, or, for a version with no current check run, the
// version itself (bound to this exact code).
export function testsPauseItems(gate) {
  if (!gate || gate.ok) return [];
  return gate.verdict !== 'not-passing'
    ? [{ kind: 'version', key: 'unchecked', fp: gate.fingerprint, title: 'this version', ...(gate.sourceFingerprint ? { code: gate.sourceFingerprint } : {}) }]
    : gate.problems.map(partItem);
}

// aiWorkPause — while the AI still has work on the checks, what the owner's
// own "deploy anyway" (or "keep trying") is recorded against: the current
// gate and its items. null when the checks are not the AI's work right now.
export function aiWorkPause(projectDir) {
  const root = projectRootFor(projectDir);
  const gate = testGateVerdict(root);
  if (gate.ok) return null;
  const lookup = deployItemLookup(root);
  if (!testGateAIWork(gate, (i) => Boolean(lookup(i)))) return null;
  return {
    kind: 'test-gate',
    pause: 'tests-not-passing',
    fingerprint: gate.fingerprint,
    verdict: gate.verdict,
    legacy: [{ fingerprint: gate.fingerprint, pause: 'test-gate' }],
    decide: testsPauseItems(gate),
    gate,
  };
}

// writeSilentTestGate — the AI's turn on the checks (deploy or guard): nothing
// is shown to the owner, but their own "deploy anyway" or "keep trying" can
// still reach it. It never uses up on another message.
// A pause the owner was shown and has not answered yet is never replaced:
// their reply is about what they read (Spec 1-D). Once they answered it, the
// AI's next turn takes its place.
export function writeSilentTestGate(projectDir, gate) {
  try {
    const root = projectRootFor(projectDir);
    let shown = null;
    try { shown = JSON.parse(readFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), 'utf-8')); } catch { /* none */ }
    if (shown?.fingerprint && !shown.silent && !shown.answered) return;
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), `${JSON.stringify({
      kind: 'test-gate',
      silent: true,
      pause: 'tests-not-passing',
      fingerprint: gate.fingerprint,
      verdict: gate.verdict,
      items: gate.problems.map((p, i) => ({ n: i + 1, id: p.id, title: p.title, status: p.status })),
      legacy: [{ fingerprint: gate.fingerprint, pause: 'test-gate' }],
      decide: testsPauseItems(gate),
      sourceFingerprint: gate.sourceFingerprint,
      at: new Date().toISOString(),
    }, null, 2)}\n`);
  } catch { /* best effort */ }
}

// partFingerprint — one part's answer key: its words and its result. A stored
// answer for a part ("deploy anyway") holds until either changes.
export function partFingerprint(scenario, status) {
  return sha256(`part\u0000${scenarioFingerprint(scenario)}\u0000${status}`).slice(0, 24);
}

// testGateAIWork — what the AI still has to do before the owner is asked:
// 'check' (this version has no current check run), 'fix' (parts fail or have
// no check, rounds left), or null. `answered(part)` — the owner already chose
// for that part (it is not the AI's work any more).
// `answered(item)` takes a pause item (testsPauseItems): the owner already
// chose for it, so it is not the AI's work any more.
export function testGateAIWork(verdict, answered = () => false) {
  if (!verdict || verdict.ok) return null;
  if (verdict.verdict === 'missing' || verdict.verdict === 'stale' || verdict.verdict === 'changed') {
    if (verdict.checkGaveUp) return null;
    return testsPauseItems(verdict).every((i) => answered(i)) ? null : 'check';
  }
  if (verdict.gaveUp) return null;
  const fixable = verdict.problems.filter((p) => (p.status === STATUS.failed || p.status === STATUS.notWritten) && !answered(partItem(p)));
  return fixable.length ? 'fix' : null;
}

// progressLine — the one line the owner sees between the AI's rounds.
export function progressLine(verdict) {
  if (verdict.verdict === 'missing' || verdict.verdict === 'stale' || verdict.verdict === 'changed') return OWNER_TEXT.checkingNow;
  return OWNER_TEXT.progress({ ...(verdict.progress ?? {}), round: Math.min(verdict.round + 1, MAX_FIX_ATTEMPTS) });
}

// testGateAIOrder — the work order for the AI (never shown to the owner).
export function testGateAIOrder(verdict) {
  if (verdict.verdict === 'missing' || verdict.verdict === 'stale' || verdict.verdict === 'changed') {
    return 'this version has not been checked yet. Run `piezas test` (write any check that is missing, fix what fails, run it again), then deploy again. ' +
      'Do not ask the owner anything about the checks; pass on only the one progress line it prints.';
  }
  const failed = verdict.problems.filter((p) => p.status === STATUS.failed).length;
  const missing = verdict.problems.filter((p) => p.status === STATUS.notWritten).length;
  const what = [failed ? `${failed} check${failed === 1 ? '' : 's'} failed` : '', missing ? `${missing} ha${missing === 1 ? 's' : 've'} no check yet` : ''].filter(Boolean).join(' / ');
  return `${what} (round ${verdict.round} of ${MAX_FIX_ATTEMPTS}). Fix and write them, then run \`npx piezas test\` again, then deploy. ` +
    'Do not ask the owner whether to keep fixing; pass on only the one progress line. After the third round the deploy asks them, once, if anything is left.';
}

// recordKeepTrying — the owner's "keep trying": three more rounds from now.
export function recordKeepTrying(root, said, via) {
  const verdict = testGateVerdict(root);
  const decisions = readDecisions(root);
  decisions.keepTrying = { from: verdict.rounds, said: String(said).slice(0, 200), via, at: new Date().toISOString() };
  delete decisions.checkAttempts;
  writeDecisions(root, decisions);
}

// namesUpTo — quoted names, the first `max`, then "and N more".
function namesUpTo(items, max) {
  const names = items.slice(0, max).map((s) => q(s.title));
  if (items.length > max) return `${names.join(', ')}, ${OWNER_TEXT.andMore(items.length - max)}`;
  return joinWords(names);
}

// summaryLines — the parts counted by group, one line per non-empty group:
// works (count only), doesn't work (the first 8 names, then "and N more"), no check yet (five
// names), couldn't be checked (with why and what to do), skipped, and one
// question per changed check.
export function summaryLines(parts) {
  const by = (status) => parts.filter((p) => p.status === status);
  const lines = [];
  const passed = by(STATUS.passed);
  const failed = by(STATUS.failed);
  const notWritten = by(STATUS.notWritten);
  const needsHelp = by(STATUS.needsHelp);
  const skipped = by(STATUS.skipped);
  const changed = by(STATUS.changedChecks);
  if (passed.length) lines.push(`✓ ${OWNER_TEXT.summary.passed(passed.length)}`);
  if (failed.length) lines.push(`✗ ${OWNER_TEXT.summary.failed(failed.length, namesUpTo(failed, 8))}`);
  if (notWritten.length) lines.push(`○ ${OWNER_TEXT.summary.notWritten(notWritten.length, namesUpTo(notWritten, 5))}`);
  // Parts that could not be checked, grouped by what the owner can do about it.
  const reasons = new Map();
  for (const p of needsHelp) {
    const { why, act } = needsHelpWords(p.needs);
    const key = `${why}\u0000${act}`;
    if (!reasons.has(key)) reasons.set(key, { why, act, items: [] });
    reasons.get(key).items.push(p);
  }
  for (const { why, act, items } of reasons.values()) lines.push(`? ${OWNER_TEXT.summary.needsHelp(items.length, namesUpTo(items, 5), why, act)}`);
  if (skipped.length) lines.push(`– ${OWNER_TEXT.summary.skipped(skipped.length, namesUpTo(skipped, 5))}`);
  for (const p of changed) {
    const name = checkChangeName(p);
    lines.push(`! ${OWNER_TEXT.changedCheck(name, OWNER_TEXT.changedCheckReply(name))}`);
  }
  return lines;
}

// testGateLines — the plain stop message: the parts counted by group, not
// listed ("list" shows them all). The same words in the terminal, the guard
// and the AI's relay. Only what is shown changes here: the stop's record
// (testGateVerdict's fingerprint) is keyed on the parts and their results.
// onlyNeedsCheckAgain — the app changed (or its check is old) and nothing was
// failing or missing: it only needs its checks run again.
export function onlyNeedsCheckAgain(verdict) {
  return (verdict.verdict === 'changed' || verdict.verdict === 'stale') && !(verdict.problems ?? []).length;
}

function dayOf(iso) {
  const at = new Date(iso);
  return Number.isFinite(at.getTime()) ? at.toLocaleDateString('en-US', { month: 'long', day: 'numeric' }) : '';
}

export function testGateLines(verdict) {
  const recheck = onlyNeedsCheckAgain(verdict);
  // Nothing failing but the app changed: what passed, passed on an earlier
  // version, so it is not shown as "checked and work".
  const passed = (verdict.passed ?? []).map((p) => ({ ...p, status: STATUS.passed }));
  const parts = [...(recheck ? [] : passed), ...verdict.problems, ...verdict.notes];
  const lines = [OWNER_TEXT.gateHeader[verdict.verdict] ?? OWNER_TEXT.gateHeader['not-passing']];
  if (verdict.gaveUp) lines.push(OWNER_TEXT.gaveUp(verdict.round));
  const summary = summaryLines(parts);
  const day = recheck && passed.length ? dayOf(verdict.ranAt) : '';
  if (day) summary.unshift(`✓ ${OWNER_TEXT.summary.passedLastCheck(passed.length, day)}`);
  if (summary.length) lines.push(OWNER_TEXT.summaryHeader, ...summary.map((l) => `  ${l}`));
  lines.push(OWNER_TEXT.nothingLive, '', ...gateChoiceLines(verdict));
  return lines;
}

// gateChoiceLines — the choices under the stop: check again (the app only
// needs checking), keep trying (parts still fail after the AI's rounds), and
// always deploy anyway. Only rewritten checks waiting: just deploy anyway.
export function gateChoiceLines(verdict, { others = false } = {}) {
  const unchecked = verdict.verdict === 'missing' || verdict.verdict === 'stale' || verdict.verdict === 'changed';
  const fixable = (verdict.problems ?? []).some((p) => p.status === STATUS.failed || p.status === STATUS.notWritten);
  const anyway = others ? OWNER_TEXT.deployAnywayAll : OWNER_TEXT.deployAnywayChoice;
  if (unchecked) {
    return [OWNER_TEXT.choicesHeader, `  ${OWNER_TEXT.checkAgainChoice}`, `  ${anyway}`, OWNER_TEXT.answerHintRecheck];
  }
  if (fixable) {
    return [OWNER_TEXT.choicesHeader, `  ${OWNER_TEXT.keepTryingChoice}`, `  ${anyway}`, OWNER_TEXT.answerHint];
  }
  return [others ? OWNER_TEXT.answerHintAll : OWNER_TEXT.answerHintDeploy];
}

// testGateItems — every part, in the order "list" shows them. The parts that
// hold the deploy up come first, numbered, so "skip 2" names one of them.
export function testGateItems(verdict) {
  return [
    ...verdict.problems.map((p, i) => ({ n: i + 1, id: p.id, title: p.title, status: p.status, ...(p.plain ? { plain: p.plain } : {}) })),
    ...verdict.notes.map((p) => ({ id: p.id, title: p.title, status: p.status, ...(p.needs ? { needs: p.needs } : {}) })),
    // Nothing failing but the app changed: what passed, passed on an earlier
    // version ("passed the last check", never "works").
    ...(verdict.passed ?? []).map((p) => ({ id: p.id, title: p.title, status: STATUS.passed, ...(onlyNeedsCheckAgain(verdict) ? { lastCheck: true } : {}) })),
  ];
}

// testGateListLines — the owner's "list": every part by name.
const LIST_MARKS = { passed: '✓', failed: '✗', 'not-written': '○', 'needs-help': '?', skipped: '–', 'changed-checks': '!' };
export function partListLines(parts) {
  return [OWNER_TEXT.listHeader, ...parts.map((p) => `  ${p.n ? `${p.n}. ` : ''}${LIST_MARKS[p.status]} ${OWNER_TEXT.listItem[p.status](p)}`)];
}

export function testGateListLines(verdict) {
  return partListLines(testGateItems(verdict));
}

// The AI-facing line under the CLI's deploy stop (`piezas deploy` prints no
// result object, so it points at what the AI can see): when an agent drives
// the deploy, the full list is printed right below the stop.
export const GATE_LIST_NEXT = 'Every part by name is listed right below, under "Every part of the app:", for you; show it to the owner only if they ask.';
export const GATE_LIST_NEXT_TERMINAL = 'The owner answers at the prompt.';
const LIST_REPLY = /^(?:(?:show|see|give)(?: me)?(?: the)? )?(?:full )?list(?: (?:them|all|everything|every part|all parts|the parts))?(?: please)?$/;

export function isListReply(said) {
  return LIST_REPLY.test(gateText(said));
}

// reportButtonOwnerOff — the owner answered "off" for the Report a problem
// button, or chose "deploy anyway" when a deploy paused for it missing.
export function reportButtonOwnerOff(root) {
  try {
    if (JSON.parse(readFileSync(join(root, 'piezas.manifest.json'), 'utf-8'))?.reportButton === false) return true;
  } catch { /* no manifest */ }
  return ownerChosePause(root, 'report-button-missing');
}

// testGateApproved — the owner's own "deploy anyway" for this exact pause, in
// the protocol state or (an app without it) .piezas/owner-approvals.json.
export function testGateApproved(projectDir, fingerprint) {
  return deployRiskApproved(projectDir, fingerprint);
}

export function writePendingTestGate(projectDir, verdict) {
  const root = projectRootFor(projectDir);
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), `${JSON.stringify({
    kind: 'test-gate',
    fingerprint: verdict.fingerprint,
    verdict: verdict.verdict,
    ...(verdict.gaveUp ? { gaveUp: true } : {}),
    items: verdict.problems.map((p, i) => ({ n: i + 1, id: p.id, title: p.title, status: p.status })),
    message: testGateLines(verdict).join('\n'),
    list: testGateListLines(verdict).join('\n'),
    ...(verdict.sourceFingerprint ? { sourceFingerprint: verdict.sourceFingerprint } : {}),
    at: new Date().toISOString(),
  }, null, 2)}\n`);
  // The rewritten-check question is never marked asked here: an agent-driven
  // deploy's stop lands in the AI's tool result, which the owner may never
  // see. Only the Stop hook marks it, when the AI's final message relays the
  // question itself (markCheckChangeAsked).
}

export function pendingTestGate(projectDir) {
  const root = projectRootFor(projectDir);
  try {
    const data = JSON.parse(readFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), 'utf-8'));
    return data?.kind === 'test-gate' ? data : null;
  } catch {
    return null;
  }
}

export function recordSkips(root, items, said, via) {
  const decisions = readDecisions(root);
  const at = new Date().toISOString();
  decisions.skipped = { ...decisions.skipped };
  for (const item of items) decisions.skipped[item.id] = { title: item.title, said: String(said).slice(0, 200), via, at };
  writeDecisions(root, decisions);
}

// Parts named by title. Matching is on the whole title (case-insensitive,
// spaces collapsed), longest title first, and each match is taken out of the
// text, so "skip Add a contact note" never also names "Add a contact". Only
// when no whole title is there is a partial name tried: it must fit exactly
// one part; when it fits several, the owner is asked which (candidates).
function titleRe(title) {
  return new RegExp(`(^|[^a-z0-9])${escapeRegExp(gateText(title))}(?![a-z0-9])`);
}

function titlesIn(text, items) {
  let rest = gateText(text);
  const picked = [];
  const titled = items.filter((i) => gateText(i.title)).sort((a, b) => gateText(b.title).length - gateText(a.title).length);
  for (const item of titled) {
    const re = titleRe(item.title);
    if (re.test(rest)) {
      picked.push(item);
      rest = rest.replace(re, '$1 ');
    }
  }
  return { picked, rest };
}

// partialParts — the parts whose title contains this partial name (whole words).
function partialParts(name, items) {
  const text = gateText(name).replace(/^["“']+|["”']+$/g, '').trim();
  if (text.length < 3 || /^\d+$/.test(text)) return [];
  return items.filter((i) => gateText(i.title) && titleRe(text).test(gateText(i.title)));
}

const inListOrder = (items, picked) => items.filter((i) => picked.has(i));

// skipPick — the owner's "skip ..." reply: null when it is not one; else the
// parts it names ([] when unclear) and, for a partial name that fits several
// parts, those parts as candidates.
// An explicit skip: "skip ...", or "leave ... unchecked / out / for now".
// "ok leave it" (leave it as it is) is not a skip.
const SKIP_START = /^(?:please\s+|ok,?\s+|okay,?\s+)?skip\b/;
const LEAVE_SKIP = /^(?:please\s+|ok,?\s+|okay,?\s+)?leave\b.*\b(?:unchecked|out|for now)\b/;
function skipPick(said, items) {
  const text = gateText(said);
  if (!(SKIP_START.test(text) || LEAVE_SKIP.test(text)) || HANDS_BACK.test(text)) return null;
  if (/\b(all|everything|them all|all of them|both)\b/.test(text)) return { targets: items, candidates: [] };
  const picked = new Set();
  const titled = titlesIn(text, items);
  for (const item of numbersOnly(titled.rest.replace(/^\s*(?:please\s+|ok,?\s+|okay,?\s+)?(?:skip|leave)\b/, ' '), items)) picked.add(item);
  for (const item of titled.picked) picked.add(item);
  if (!picked.size && items.length === 1 && /\b(this one|that one|it|this|that|for now)\b|^skip$|^skip (?:one )?for now$/.test(text)) picked.add(items[0]);
  if (picked.size) return { targets: inListOrder(items, picked), candidates: [] };
  const name = withoutFiller(text.replace(/^(?:please\s+|ok,?\s+|okay,?\s+)?(?:skip|leave)\b/, '').replace(/\bfor now\b/g, ' ').replace(/^\s*(?:the|one|part)\b/, ' '));
  const partial = name ? partialParts(name, items) : [];
  if (partial.length === 1) return { targets: partial, candidates: [] };
  return { targets: [], candidates: partial };
}

// skipTargets — which listed parts an owner's "skip ..." reply names, or null
// when it is not a skip reply, or [] when it is one but unclear.
export function skipTargets(said, items) {
  return skipPick(said, items)?.targets ?? null;
}

// readGateReply — the owner's answer to the deploy stop, or null when the text
// is not one. The owner may answer with the number of a choice or its words:
//   1 / keep fixing            -> { choice: 'keep' }
//   2 / skip (no part named)   -> { choice: 'skip', targets: [] }  (ask which)
//   2 1 / 2 <name> / skip 1    -> { choice: 'skip', targets: [...] }
//   3 / deploy anyway          -> { choice: 'deploy' }
// A number counts only as a short reply: the number alone, optionally with a
// few words that say the same thing ("3 please", "2. skip 1", "3 deploy
// anyway"), so a number inside an unrelated message never answers.
const GATE_FILLER = /\b(?:please|pls|thanks|thank you|ok|okay|yes|sure)\b/g;
const GATE_KEEP_WORDS = /^(?:keep trying|try again|keep fixing|keep going|fix it|fix them|keep working|continue fixing|check again)$/;
const GATE_DEPLOY_WORDS = /^(?:deploy anyway|deploy it anyway|deploy|deploy it|go live|go live anyway|put it live|put it live anyway)$/;
export const GATE_REPLY_MAX_CHARS = 160;

function gateText(said) {
  return String(said || '').toLowerCase().replace(/[’]/g, "'").replace(/\s+/g, ' ').trim().replace(/[.!]+$/, '').trim();
}

function withoutFiller(text) {
  return text.replace(GATE_FILLER, ' ').replace(/[,;:.!()-]+/g, ' ').replace(/\s+/g, ' ').trim();
}

// numbersOnly — the parts a text names by number, counted only when the text
// is just numbers ("1", "1 and 3", "#2 for now"): a digit in a longer message
// (or inside a part's title, taken out before) never names a part.
const NUMBER_ONLY_WORDS = /\b(?:skip|leave|part|parts|number|one|the|for now|unchecked|only|just|and|out)\b|#/g;
function numbersOnly(text, items) {
  const nums = [...String(text).matchAll(/\b(\d{1,3})\b/g)].map((m) => Number(m[1]));
  if (!nums.length) return [];
  const rest = withoutFiller(String(text).replace(/\b\d{1,3}\b/g, ' ').replace(NUMBER_ONLY_WORDS, ' '));
  if (rest) return [];
  return nums.map((n) => items.find((i) => i.n === n)).filter(Boolean);
}

// pickParts — the listed parts a short text names, by whole name, or by
// number when the rest of the text is just numbers.
export function pickParts(text, items) {
  const lower = gateText(text);
  const picked = new Set();
  const titled = titlesIn(lower, items);
  for (const item of numbersOnly(titled.rest, items)) picked.add(item);
  for (const item of titled.picked) picked.add(item);
  return inListOrder(items, picked);
}

// A number answers only a stop that showed a numbered menu (the older stop's
// "1. Keep fixing / 2. Skip / 3. Deploy anyway"); the one pause shows none, so
// a "3" meant for anything else never puts a version live.
export const NUMBERED_MENU = /^\s*[123][.)]\s+(?:keep|skip|leave|deploy)/im;
export function showedNumberedMenu(message) {
  return NUMBERED_MENU.test(String(message ?? ''));
}

// exactDeployAnyway — the owner's reply is the exact words "deploy anyway"
// (any case, a trailing full stop or "!" allowed), nothing else.
export function exactDeployAnyway(said) {
  return gateText(said) === DEPLOY_ANYWAY;
}

// needsExactWords — a pause that holds a broken Piezas rule or a missing
// setting is answered only by the exact words "deploy anyway".
export function needsExactWords(decide) {
  return (Array.isArray(decide) ? decide : []).some((i) => i?.kind === 'rule' || i?.kind === 'setting');
}

export function readGateReply(said, items = [], { numbers = false } = {}) {
  const text = gateText(said);
  if (!text || HANDS_BACK.test(text)) return null;
  const numbered = numbers ? /^([123])(?:\s*[.):,-]\s*|\s+|$)(.*)$/.exec(text) : null;
  if (numbered) {
    if (text.length > GATE_REPLY_MAX_CHARS) return null;
    const rest = withoutFiller(numbered[2]);
    if (numbered[1] === '1') return !rest || GATE_KEEP_WORDS.test(rest) ? { choice: 'keep', numbered: true } : null;
    if (numbered[1] === '3') return !rest || GATE_DEPLOY_WORDS.test(rest) ? { choice: 'deploy', numbered: true } : null;
    const named = numbered[2].replace(/^(?:skip|leave)(?: one)?(?: for now)?\b/, '').replace(/\bfor now\b/, '').trim();
    const plain = withoutFiller(named);
    if (!plain || plain === 'unchecked') return { choice: 'skip', targets: [], numbered: true };
    const targets = pickParts(named, items);
    if (targets.length) return { choice: 'skip', targets, numbered: true };
    const partial = partialParts(plain, items);
    if (partial.length === 1) return { choice: 'skip', targets: partial, numbered: true };
    return partial.length ? { choice: 'skip', targets: [], candidates: partial, numbered: true } : null;
  }
  if (withoutFiller(text) === DEPLOY_ANYWAY) return { choice: 'deploy' };
  const skip = skipPick(said, items);
  if (skip !== null) return { choice: 'skip', targets: skip.targets, ...(skip.candidates.length ? { candidates: skip.candidates } : {}) };
  if (/^skip one(?: for now)?$/.test(text)) return { choice: 'skip', targets: [] };
  if (/^(?:keep trying|try again|keep fixing|keep going|fix it|fix them|keep working|continue fixing|check again)\b/.test(text)) return { choice: 'keep' };
  return null;
}

// isGateChoice — is this reply shaped as an answer to the deploy stop (a
// leading 1, 2 or 3, its words, or "list")? Such a reply is never read as
// the owner OKing a rewritten check: "1 please" means keep fixing.
export function isGateChoice(said) {
  const text = gateText(said);
  if (!text) return false;
  return /^[123](?:\s*[.):,-]|\s|$)/.test(text) || readGateReply(said, []) !== null || isListReply(said);
}

// The deploy stop is answered by the owner's NEXT message after it was shown,
// within this long. Anything else they say first (or a later message) uses
// the stop up: a "3" meant for some other question never deploys.
export const GATE_REPLY_WINDOW_MS = 30 * 60 * 1000;
const WHICH_PART_WORDS = /\b(?:skip|leave|part|parts|number|one|the|for now|unchecked|only|just|and)\b|#/g;

// readWhichPartReply — the owner's answer to "which part should be left
// unchecked for now?": the parts it names by number or name, or none when
// the reply is not just that (so a number inside an unrelated message never
// counts). A partial name that fits several parts gives them as candidates.
export function readWhichPartReply(said, items = []) {
  const none = { targets: [], candidates: [] };
  const text = gateText(said);
  if (!text || text.length > GATE_REPLY_MAX_CHARS || HANDS_BACK.test(text)) return none;
  if (/^(?:skip |leave )?(?:all|both|everything|all of them|them all)(?: of them)?(?: for now)?$/.test(withoutFiller(text))) return { targets: items, candidates: [] };
  const picked = pickParts(text, items);
  if (picked.length) {
    const rest = withoutFiller(titlesIn(text, items).rest.replace(/\b\d{1,3}\b/g, ' ').replace(WHICH_PART_WORDS, ' '));
    return rest ? none : { targets: picked, candidates: [] };
  }
  const name = withoutFiller(text.replace(/^(?:skip|leave)\b/, '').replace(/\bfor now\b/g, ' ').replace(/^\s*(?:the|one|part)\b/, ' '));
  const partial = partialParts(name, items);
  if (partial.length === 1) return { targets: partial, candidates: [] };
  return { targets: [], candidates: partial };
}

export function readWhichPart(said, items = []) {
  return readWhichPartReply(said, items).targets;
}

function usePendingTestGateUp(root, pending) {
  try { writeFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), `${JSON.stringify({ ...pending, usedUp: new Date().toISOString() }, null, 2)}\n`); } catch { /* best effort */ }
}

function clearPendingTestGate(root) {
  try { rmSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), { force: true }); } catch { /* best effort */ }
}

// clearAnsweredTestGate — the owner answered the stop at the terminal: it is
// no longer waiting for a chat reply.
export function clearAnsweredTestGate(projectDir) {
  const root = projectRootFor(projectDir);
  if (pendingTestGate(root)) clearPendingTestGate(root);
}

// gateChoicesNote — the choices the AI repeats after "list": the same ones the
// stop offered. When the app only needs checking again (it changed or its
// check is old, nothing failing) there are two, and "skip" is not one.
function gateChoicesNote(verdict, items) {
  if (verdict === 'missing' || verdict === 'changed' || verdict === 'stale') {
    return `the same choices, word for word: "${OWNER_TEXT.checkAgainChoice}" and "${OWNER_TEXT.deployAnywayChoice}"`;
  }
  if (items.some((i) => i.status === STATUS.failed || i.status === STATUS.notWritten)) {
    return `the same choices, word for word: "${OWNER_TEXT.keepTryingChoice}" and "${OWNER_TEXT.deployAnywayChoice}"`;
  }
  return `"${OWNER_TEXT.answerHintDeploy}"`;
}

// rewrittenRepeatNote — after "list", each rewritten check's question is
// repeated word for word, so the owner can still answer it by name.
function rewrittenRepeatNote(items) {
  const changed = items.filter((i) => i.status === STATUS.changedChecks);
  if (!changed.length) return '';
  return `; then repeat, word for word, ${changed.map((i) => `"${OWNER_TEXT.changedCheck(checkChangeName(i), OWNER_TEXT.changedCheckReply(checkChangeName(i)))}"`).join(' and ')}`;
}

// recordTestGateReply — the UserPromptSubmit half: the owner's own reply to
// the deploy stop. Returns a note for the AI, or ''. Runs only on the owner's
// typed message (the plugin hook), never on anything the AI writes, and only
// while a deploy stop is waiting (recorded by the stop itself). Only the
// owner's next message after the stop, within GATE_REPLY_WINDOW_MS, can answer
// it; that message uses the stop up whatever it says (its choices are gone,
// but it stays the pause the owner read: their exact "deploy anyway" still
// binds to it, and a newer pause waits behind it until relayed). The one
// exception is a partial part name: the stop then waits for the next message
// only, which names the part.
export function recordTestGateReply(root, prompt, via = 'owner-reply') {
  const pending = pendingTestGate(root);
  // Nothing shown to the owner (the AI's rounds): only their own "keep
  // trying" is read, and nothing is used up by any other message.
  if (!pending?.fingerprint || pending.silent || pending.usedUp) return aiWorkReply(root, prompt, via);
  // Used up for the choices it offered, but still the pause the owner read:
  // their own "deploy anyway" binds to it, and the AI's next deploy waits
  // behind it until relayed (writeShownPause).
  usePendingTestGateUp(root, pending);
  const age = Date.now() - Date.parse(pending.at);
  if (!Number.isFinite(age) || age > GATE_REPLY_WINDOW_MS || age < -5 * 60 * 1000) return '';
  const said = String(prompt || '').trim();
  const items = Array.isArray(pending.items) ? pending.items : [];
  // "list" does not answer the stop: it shows every part, and the stop waits
  // for the owner's next message again.
  if (pending.awaiting !== 'which-part' && isListReply(said)) {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), `${JSON.stringify({ ...pending, at: new Date().toISOString() }, null, 2)}\n`);
    return `The owner asked to see every part. Show them this list as it is, then ask again: "${OWNER_TEXT.choicesHeader}" with ${gateChoicesNote(pending.verdict, items)}${rewrittenRepeatNote(items)}, and wait for their reply.\n${pending.list ?? items.map((i) => `${i.n}. ${q(i.title)}`).join('\n')}`;
  }
  // An answer closes the pause (it no longer waits for the owner).
  const skipped = (targets) => {
    clearPendingTestGate(root);
    recordSkips(root, targets, said, via);
    return `The owner chose to skip ${joinWords(targets.map((t) => q(t.title)))} for now, and it is recorded. Run the deploy again. Tell them in one sentence: "${OWNER_TEXT.skipRecorded(targets.map((t) => t.title))}"`;
  };
  // A partial name that fits several parts: ask again, naming them; the stop
  // waits for the next message only.
  const askWhichOf = (candidates) => {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(join(root, STATE_DIR, DEPLOY_RISK_FILE), `${JSON.stringify({ ...pending, awaiting: 'which-part', at: new Date().toISOString() }, null, 2)}\n`);
    return `The owner's answer fits more than one part: ${candidates.map((c) => `${c.n}. ${q(c.title)}`).join(', ')}. Ask them which one they mean, by number or full name. Do not choose for them.`;
  };
  if (pending.awaiting === 'which-part') {
    const { targets, candidates } = readWhichPartReply(said, items);
    if (targets.length) return skipped(targets);
    return candidates.length > 1 ? askWhichOf(candidates) : '';
  }
  const reply = readGateReply(said, items, { numbers: showedNumberedMenu(pending.message) });
  if (!reply) return '';
  if (reply.choice === 'skip') {
    if (pending.verdict !== 'not-passing') {
      return 'The owner asked to skip a part, but this version has to be checked again first (it changed, or the last check is too old). Run piezas test, then deploy again; tell them that in one sentence.';
    }
    if (!reply.targets.length && reply.candidates?.length > 1) return askWhichOf(reply.candidates);
    // No part named: not an answer (there is no "which part?" question).
    if (!reply.targets.length) return '';
    return skipped(reply.targets);
  }
  if (reply.choice === 'keep') {
    clearPendingTestGate(root);
    if (pending.verdict === 'changed' || pending.verdict === 'stale' || pending.verdict === 'missing') {
      return 'The owner chose to check again. Run piezas test on this version, fix what fails (up to three rounds), then deploy again. Do not ask them again before that.';
    }
    if (pending.gaveUp) {
      recordKeepTrying(root, said, via);
      return `The owner chose to keep trying: you get three more rounds. Fix what is failing, write the missing checks, run piezas test (up to ${MAX_FIX_ATTEMPTS} rounds), then deploy again. Do not ask them again before that; pass on only the progress line. Tell them in one sentence: "${OWNER_TEXT.keepTryingOk}"`;
    }
    const changed = items.filter((i) => i.status === STATUS.changedChecks);
    const explain = changed.length
      ? ` For each rewritten check (${joinWords(changed.map((i) => q(i.title)))}): restore the original check, or tell the owner in ONE plain sentence what you changed and why, then end your message with its exact line from the stop (${changed.map((i) => `"${OWNER_TEXT.changedCheck(checkChangeName(i), OWNER_TEXT.changedCheckReply(checkChangeName(i)))}"`).join(' / ')}); only their "yes" and the part's name is recorded.`
      : '';
    return `The owner chose to keep fixing. Write the missing checks, fix what is failing, run piezas test (up to ${MAX_FIX_ATTEMPTS} rounds), then deploy again. Do not ask them again before that.${explain}`;
  }
  if (needsExactWords(pending.decide) && !exactDeployAnyway(said)) {
    return `The owner answered "${said.slice(0, 60)}", which is not "deploy anyway". This pause also covers a broken Piezas rule or a missing setting, and only the owner's own exact words "deploy anyway" put it live: nothing was recorded. Do not deploy; tell them that in one sentence.`;
  }
  const { changedSince } = recordPauseAnswer(root, pending, via, said);
  clearPendingTestGate(root);
  if (changedSince) {
    return `The owner chose "deploy anyway" (they answered "${said.slice(0, 60)}") for the pause they were shown, but the code has changed since: it is recorded for that earlier version only. Run the deploy again and pass on what it prints; do not tell them this version is going live.`;
  }
  return `The owner chose "deploy anyway" (they answered "${said.slice(0, 60)}" themselves), and it is recorded. Run the deploy again now; tell them in one sentence that it is going live and that fixing the problem is still recommended.`;
}

// aiWorkReply — the owner's own "keep trying" while the AI is still on its
// rounds: recorded (three more rounds from now). Anything else: ''.
function aiWorkReply(root, prompt, via = 'owner-reply') {
  const said = String(prompt || '').trim();
  if (readGateReply(said, [])?.choice !== 'keep') return '';
  if (!aiWorkPause(root)) return '';
  recordKeepTrying(root, said, via);
  return `The owner said "keep trying" while you are still working on the checks, and it is recorded: you have three more rounds from now. Carry on (fix, write the missing checks, run piezas test, then deploy). Tell them in one sentence: "${OWNER_TEXT.keepTryingOk}"`;
}

// The owner's answer to "I changed how X is checked because ... Is that OK?"
// counts only as a short, standalone reply: the whole message is approval
// words ("yes", "ok", "yes that's fine", "sure, go ahead"), never an approval
// word inside a longer instruction ("ok, now make the header blue").
const APPROVAL_PHRASES = [
  "that's fine", 'that is fine', "that's ok", "that's okay", 'that is ok', 'that is okay', "it's fine", 'it is fine',
  "that's good", 'sounds good', 'looks good', 'all good', 'that works', 'go ahead', 'go for it', 'do it', 'fine by me',
  'ok by me', 'okay by me', 'of course', 'i agree', 'i approve', 'i accept', 'yes please',
  'yes', 'yeah', 'yep', 'yup', 'ya', 'y', 'sure', 'ok', 'okay', 'k', 'fine', 'agreed', 'approved', 'accepted',
  'accept', 'approve', 'absolutely', 'definitely', 'correct', 'right', 'good', 'great', 'perfect', 'please',
  'thanks', 'thank you', 'alright', 'all right',
].sort((a, b) => b.length - a.length);
const DECLINE_PHRASES = [
  'no', 'nope', 'nah', 'not ok', 'not okay', "that's not ok", "that's not okay", 'not fine', "don't", 'do not',
  "don't do that", 'please', 'thanks', 'keep it', 'keep the original', 'keep the original check', 'keep the check',
  'keep the checks', 'put it back', 'restore it', 'undo it', 'undo that', 'revert it', 'no way', 'no thanks',
  "i don't agree", 'i disagree', 'not really', 'thank you', 'sorry', 'keep the old check', 'keep the old one',
].sort((a, b) => b.length - a.length);
// A decline needs a real "no" word; an approval may contain none.
const DECLINE_CORE = /\b(?:no|nope|nah|not|don'?t|do not|disagree|keep|put it back|restore|undo|revert)\b/;

// Digits are kept: "yes 2" is not a bare "yes", and "1 please" is not "please".
// Letters in any script are kept, so a title like "連絡先を追加" can be named.
function replyWords(said) {
  return String(said || '').toLowerCase().replace(/[’]/g, "'").replace(/[^\p{L}\p{M}\p{N}' ]+/gu, ' ').replace(/\s+/g, ' ').trim();
}

// madeOnlyOf — true when the text is nothing but these phrases (any order).
function madeOnlyOf(text, phrases) {
  let rest = ` ${text} `;
  for (let hit = true; hit;) {
    hit = false;
    for (const phrase of phrases) {
      if (rest.includes(` ${phrase} `)) {
        rest = rest.replace(` ${phrase} `, ' ');
        hit = true;
        break;
      }
    }
  }
  return rest.trim() === '';
}

export function isStandaloneApproval(said) {
  const text = replyWords(said);
  if (!text || text.length > 60 || DECLINE_CORE.test(text)) return false;
  return madeOnlyOf(text, APPROVAL_PHRASES);
}

export function isStandaloneDecline(said) {
  const text = replyWords(said);
  if (!text || text.length > 80 || !DECLINE_CORE.test(text)) return false;
  return madeOnlyOf(text, DECLINE_PHRASES);
}

// openCheckChanges — the changed checks still waiting for the owner's OK.
export function openCheckChanges(root, pending = readCheckChange(root)) {
  const approvals = readDecisions(root).checkChangeApprovals.filter((a) => a.fingerprint === pending?.fingerprint);
  return (pending?.scenarios ?? []).filter((s) => !approvals.some((a) => (a.ids ?? []).includes(s.id)));
}

// checkChangeName — what the owner types to name a changed check: its title,
// or its scenario id when the title is blank (so "yes <name>" is never a bare
// "yes", which OKs every waiting check).
export function checkChangeName(s) {
  const title = String(s?.title ?? '').trim();
  return title || String(s?.id ?? '').trim();
}

// changedCheckLine — the stop's question for one rewritten check.
function changedCheckLine(s) {
  return OWNER_TEXT.changedCheck(checkChangeName(s), OWNER_TEXT.changedCheckReply(checkChangeName(s)));
}

const escapeRegExp = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// approvedCheckChanges — which changed checks a short reply OKs. Only a reply
// that names the check counts: "yes" and its title words or its scenario id
// ("yes Add a contact", "yes S-030"), case-insensitive. A bare "yes" OKs
// nothing, even with one check waiting (checkChangeNeedsName: the owner is
// asked which). "yes all" / "yes both" / "all good" OK every waiting check, but
// only when the question the owner saw named every one of them (`shown`).
// Only checks in `shown` (the ones the owner was asked about) can be OKed. An
// answer to the deploy stop ("1 please", "3 yes", "keep fixing") is never an
// OK. [] when it is not that.
const NAME_FILLER = /\b(?:to|for|the|check|checks|new|change|changes|on|of|with|and|one|is|was|that|this)\b/g;
// "yes both", "yes to all", "yes, all of them", "all good": every waiting check.
const ALL_WORDS = /\b(?:both|all|every|everything)\b/;
const ALL_FILLER = /\b(?:all of them|all of those|them all|every one|everyone|everything|both|all|every|to|for|of|them|those|the|checks?|ones?)\b/g;
// Emphasis after a yes ("yes 100%", "yes!!!"): a percentage is never a
// choice number or an id.
const EMPHASIS = /\b\d+(?:\.\d+)?\s*%/g;
// "all right" is a plain "alright", not "all".
const allWordsOf = (said) => replyWords(String(said || '').replace(EMPHASIS, ' ')).replace(/\ball right\b/g, 'alright');
// isAllApproval — "yes all", "yes both", "all good", "ok all", "yes everything".
function isAllApproval(said) {
  const words = allWordsOf(said);
  if (!ALL_WORDS.test(words) || words.length > 60 || DECLINE_CORE.test(words)) return false;
  const rest = words.replace(ALL_FILLER, ' ').replace(/\s+/g, ' ').trim();
  return Boolean(rest) && madeOnlyOf(rest, APPROVAL_PHRASES);
}
export function approvedCheckChanges(said, waiting, shown = waiting) {
  const asked = waiting.filter((s) => shown.some((x) => x.id === s.id));
  if (!asked.length || isGateChoice(said)) return [];
  // With one check waiting, "all good" names nothing more than "yes" does.
  if (isAllApproval(said)) return waiting.length > 1 && asked.length === waiting.length ? [...waiting] : [];
  let raw = String(said || '');
  if (raw.length > 200 + Math.max(...asked.map((s) => String(s.title ?? '').length))) return [];
  const picked = [];
  // Ids first: replyWords drops digits, so an id is matched on the raw text
  // (as a whole token) and taken out before the title words are read.
  for (const s of asked) {
    const id = String(s?.id ?? '').trim();
    if (!id) continue;
    const re = new RegExp(`(^|[^a-z0-9_-])${escapeRegExp(id)}(?![a-z0-9_-])`, 'i');
    if (re.test(raw)) {
      picked.push(s);
      raw = raw.replace(re, '$1 ');
    }
  }
  let text = replyWords(raw.replace(EMPHASIS, ' '));
  if (!text) return [];
  for (const s of [...asked].sort((a, b) => String(b.title).length - String(a.title).length)) {
    if (picked.includes(s)) continue;
    const name = replyWords(s.title);
    if (name && ` ${text} `.includes(` ${name} `)) {
      picked.push(s);
      text = ` ${text} `.replace(` ${name} `, ' ').trim();
    }
  }
  if (!picked.length) return [];
  const rest = text.replace(NAME_FILLER, ' ').replace(/\s+/g, ' ').trim();
  if (!rest || DECLINE_CORE.test(rest) || !madeOnlyOf(rest, APPROVAL_PHRASES)) return [];
  return waiting.filter((s) => picked.includes(s));
}

// readWhichCheckReply — the owner's answer at the terminal's "Which check did
// you mean?" prompt: "yes" and a name, or just the name (whole title, its id,
// or a partial name that fits exactly one waiting check). [] when unclear.
export function readWhichCheckReply(said, waiting) {
  const approved = approvedCheckChanges(said, waiting);
  if (approved.length) return approved;
  const text = replyWords(said);
  if (!text || text.length > 120 || DECLINE_CORE.test(text)) return [];
  const exact = waiting.filter((s) => replyWords(s.title) === text || String(s.id ?? '').toLowerCase() === String(said).trim().toLowerCase());
  if (exact.length === 1) return exact;
  if (text.length < 3 || /^\d+$/.test(text)) return [];
  const partial = waiting.filter((s) => ` ${replyWords(s.title)} `.includes(` ${text} `));
  return partial.length === 1 ? partial : [];
}

// checkChangeNeedsName — the owner said yes without saying which: a bare
// "yes" (one check waiting or several), "yes" and a number ("yes 2"), or "yes
// all" when the question they saw did not name every waiting check.
export function checkChangeNeedsName(said, waiting, shown = waiting) {
  if (!waiting.length || isGateChoice(said) || approvedCheckChanges(said, waiting, shown).length) return false;
  if (isAllApproval(said)) return true;
  const words = replyWords(String(said || '').replace(EMPHASIS, ' '));
  const text = words.replace(/\b\d+\b/g, ' ').replace(/\s+/g, ' ').trim();
  if (!text || text.length > 60 || DECLINE_CORE.test(text)) return false;
  return madeOnlyOf(text, APPROVAL_PHRASES);
}

// asksCheckChange — which rewritten checks this AI message asks the owner
// about: the ids whose reply the stop's line asks for ("reply "yes <name>""),
// quotes, markdown and line breaks aside, so a relay that keeps the request
// counts even when its wording drifts. For the which-check question
// (OWNER_TEXT.whichCheck), the checks that question follows up on
// (`pending.whichIds`). Anything else — a title and "check" and a "?", "Is
// that OK?", a line saying no reply is needed — asks nothing. [] when none.
const relayText = (t) => String(t || '').toLowerCase()
  .replace(/^\s*>\s?/gm, '').replace(/[‘’“”"'«»`*_]/g, '').replace(/\s+/g, ' ').trim();
const asksWhichCheck = (said) => said.includes('which check did you mean') && said.includes('reply yes and its name');
export function asksCheckChange(text, pending) {
  const said = relayText(text);
  if (!said) return [];
  const scenarios = pending?.scenarios ?? [];
  const ids = scenarios.filter((s) => {
    const name = relayText(checkChangeName(s));
    return name && new RegExp(`reply ${escapeRegExp(relayText(OWNER_TEXT.changedCheckReply(name)))}(?![\\p{L}\\p{N}])`, 'u').test(said);
  }).map((s) => s.id);
  const which = asksWhichCheck(said) ? scenarios.find((s) => checkChangeName(s)) : null;
  if (which) {
    const followed = Array.isArray(pending?.whichIds) && pending.whichIds.length ? pending.whichIds : [which.id];
    for (const id of followed) if (!ids.includes(id) && scenarios.some((s) => s.id === id)) ids.push(id);
  }
  return ids;
}

// lastAssistantText — the AI's last message in this turn, from the Stop
// payload (`last_assistant_message`, Claude Code and Codex) or, when that is
// missing, the last assistant entry of the session transcript.
export function lastAssistantText(payload) {
  if (typeof payload?.last_assistant_message === 'string') return payload.last_assistant_message;
  const path = typeof payload?.transcript_path === 'string' ? payload.transcript_path : '';
  if (!path || !existsSync(path)) return '';
  try {
    const lines = readFileSync(path, 'utf-8').trim().split('\n').slice(-200).reverse();
    for (const line of lines) {
      let entry;
      try { entry = JSON.parse(line); } catch { continue; }
      const msg = entry?.message ?? entry?.payload ?? entry;
      const role = msg?.role ?? entry?.type;
      if (role !== 'assistant') continue;
      const content = msg?.content;
      if (typeof content === 'string') return content;
      if (Array.isArray(content)) {
        const text = content.filter((c) => c && (c.type === 'text' || c.type === 'output_text')).map((c) => c.text).join('\n');
        if (text) return text;
      }
    }
  } catch { /* unreadable transcript: nothing asked */ }
  return '';
}

// markCheckChangeAsked — the Stop half, and the only place the question is
// marked asked for the chat: when the AI's message at the end of a turn asks
// the owner about a rewritten check in Piezas's own words, those checks are
// marked as asked (askedIds), so the owner's NEXT reply can OK them by name.
// When it does not, any earlier mark is cleared: the owner's next reply
// answers whatever the AI asked instead.
export function markCheckChangeAsked(root, payload) {
  const pending = readCheckChange(root);
  if (!pending?.fingerprint || !Array.isArray(pending.scenarios) || !pending.scenarios.length) return false;
  const text = lastAssistantText(payload);
  const ids = asksCheckChange(text, pending);
  if (!ids.length) {
    // A stop that follows a hold (the AI kept working): the owner has already
    // seen the message that asked, so its mark stays.
    if (!payload?.stop_hook_active) clearCheckChangeAsked(root, pending);
    return false;
  }
  const { whichIds: _followed, askedWhich: _was, ...rest } = pending;
  // After the which-check question, the bare name answers it.
  const askedWhich = asksWhichCheck(relayText(text)) ? { askedWhich: true } : {};
  writeStateJson(root, CHECK_CHANGE_FILE, { ...rest, askedAt: new Date().toISOString(), askedIds: ids, ...askedWhich });
  return true;
}

// clearCheckChangeAsked — the question is no longer open (the AI did not
// relay it, or the owner answered the stop in the terminal).
export function clearCheckChangeAsked(root, pending = readCheckChange(root)) {
  if (!pending || !['askedAt', 'askedIds', 'whichIds', 'askedWhich'].some((k) => k in pending)) return;
  const { askedAt: _gone, askedIds: _ids, whichIds: _which, askedWhich: _was, ...rest } = pending;
  writeStateJson(root, CHECK_CHANGE_FILE, rest);
}

// namedChecks — the checks a reply names, by whole title or by id.
function namedChecks(said, checks) {
  const text = ` ${replyWords(said)} `;
  return checks.filter((s) => {
    const name = replyWords(s.title);
    const id = String(s.id ?? '').trim();
    return (name && text.includes(` ${name} `)) || (id && new RegExp(`(^|[^a-z0-9_-])${escapeRegExp(id)}(?![a-z0-9_-])`, 'i').test(said));
  });
}

// recordCheckChangeReply — the owner's OK for a rewritten check. Counts only
// when the AI actually asked about it in Piezas's words (markCheckChangeAsked),
// only for the owner's next message, and only when that message names the
// check ("yes Add a contact", "yes S-001") or says "yes all" / "yes both"
// after a question that named every waiting check. A bare "yes" is never an
// OK: the AI is told to ask which. Returns a note for the AI, or ''.
export function recordCheckChangeReply(root, prompt) {
  const pending = readCheckChange(root);
  if (!pending?.fingerprint || !Array.isArray(pending.scenarios) || !pending.scenarios.length) return '';
  const said = String(prompt || '').trim();
  const askedAt = Date.parse(pending.askedAt);
  if (!Number.isFinite(askedAt)) {
    // Not asked in Piezas's words, so not recorded, but the AI hears why.
    const open = openCheckChanges(root, pending);
    const meant = isGateChoice(said) ? [] : approvedCheckChanges(said, open, open);
    if (!meant.length) return '';
    return `The owner's reply names ${joinWords(meant.map((s) => q(s.title)))}, but it is not recorded: your last message did not ask them in Piezas's words. Tell them in one plain sentence what you changed and why, then end your message with ${meant.map((s) => `"${changedCheckLine(s)}"`).join(' ')}, and wait for their reply.`;
  }
  // "list" shows the parts; the question still waits for the real answer.
  if (isListReply(said)) return '';
  // One reply per question: whatever the owner says next uses it up.
  const { askedAt: _used, askedIds: _ids, whichIds: _which, askedWhich, ...rest } = pending;
  writeStateJson(root, CHECK_CHANGE_FILE, rest);
  const age = Date.now() - askedAt;
  if (age > ATTESTATION_MAX_AGE_MS || age < -5 * 60 * 1000) return '';
  const open = openCheckChanges(root, pending);
  const askedIds = Array.isArray(pending.askedIds) ? pending.askedIds : [];
  const shown = open.filter((s) => askedIds.includes(s.id));
  if (!shown.length) return '';
  if (!said || HANDS_BACK.test(said.toLowerCase())) return '';
  const titles = shown.map((s) => q(s.title));
  const askWhich = (why) => {
    // The AI asks which; the Stop hook marks that question asked when its
    // final message relays it, for the same checks.
    writeStateJson(root, CHECK_CHANGE_FILE, { ...rest, whichIds: shown.map((s) => s.id) });
    return `${why}; nothing is recorded. Ask them exactly: "${OWNER_TEXT.whichCheck(checkChangeName(shown[0]))}" Do not run --accept-change until their answer names one.`;
  };
  // An answer to the deploy stop ("1 please", "3 yes") is that, never an OK.
  // "3 yes Add a contact" mixes both: neither counts, and the AI asks again.
  if (isGateChoice(said)) {
    const after = said.replace(/^\s*[13](?:\s*[.):,-]\s*|\s+)/, '');
    if (after !== said && approvedCheckChanges(after, open, shown).length) {
      return askWhich(`The owner's reply ("${said.slice(0, 80)}") mixed an answer to the deploy stop with an OK for a rewritten check, so nothing was deployed. Ask them to answer one thing at a time`);
    }
    return '';
  }
  if (checkChangeNeedsName(said, open, shown)) {
    return askWhich(`The owner said yes but did not say which rewritten check they mean (${joinWords(titles)})`);
  }
  let approved = approvedCheckChanges(said, open, shown);
  if (!approved.length && askedWhich) approved = readWhichCheckReply(said, shown);
  if (approved.length) {
    recordCheckChangeApproval(root, { ...pending, scenarios: approved }, said, 'owner-reply');
    const names = approved.map((s) => q(s.title));
    return `The owner said OK to changing how ${joinWords(names)} ${names.length === 1 ? 'is' : 'are'} checked, and it is recorded. Now run ${approved.map((s) => `piezas test --accept-change ${s.id} --reason "<one plain sentence: what changed and why>"`).join(', then ')}, then run piezas test again.`;
  }
  const named = namedChecks(said, shown);
  const declined = named.length === 1 && DECLINE_CORE.test(replyWords(said)) ? named
    : !named.length && isStandaloneDecline(said) ? shown : [];
  if (declined.length) {
    const names = declined.map((s) => q(s.title));
    return `The owner did NOT agree to changing how ${joinWords(names)} ${names.length === 1 ? 'is' : 'are'} checked. Put the original checks back and make the app pass them, then run piezas test again.`;
  }
  if (named.length) return askWhich(`The owner's reply mentions ${joinWords(named.map((s) => q(s.title)))}, but it is not clear what they want`);
  return '';
}

// ===========================================================================
// The separate test copy of the app, and its made-up data
// ===========================================================================

export function testAppName(appName) {
  return `${appName} (test)`;
}

// setupTestApp — "<App name> (test)" in the owner's Piezas account, through the
// same create-app + create-key calls init uses. Its key goes to .env as
// PIEZAS_TEST_API_KEY and is never printed. Returns { ok, status, message }.
export async function setupTestApp(projectDir, options = {}) {
  const env = options.env ?? process.env;
  const root = projectRootFor(projectDir);
  const envPath = join(root, '.env');
  const manifestPath = join(root, 'piezas.manifest.json');
  const manifest = readManifestSafe(root) ?? {};
  const say = (message) => { if (!options.quiet) log(`  ${message}`); return message; };
  if (isSandboxProject(root)) return { ok: false, status: 'sandbox', message: say(OWNER_TEXT.testCopySandbox) };
  const baseName = manifest.appName || basename(root);
  const name = testAppName(baseName);
  if (testKeyFor(root, env) && manifest.testApp?.appId) {
    ensureTestUser(envPath, name);
    return { ok: true, status: 'exists', appName: manifest.testApp.appName ?? name, message: say(OWNER_TEXT.testCopyReady(manifest.testApp.appName ?? name)) };
  }
  const credentials = platformCredentials(root, env);
  if (!credentials) return { ok: false, status: 'not-signed-in', message: say(OWNER_TEXT.testCopyNotSignedIn) };
  const fetchFn = platformFetch(root, options);
  const apiBase = resolveApiBase(options, env, credentials.apiBase || DEFAULT_API_BASE_URL);
  const tenantPath = `${adminBaseUrl(apiBase)}/v1/tenants/${credentials.tenantId}`;
  const http = { token: credentials.cliToken, timeoutMs: options.httpTimeoutMs };
  try {
    let app;
    // The project's own test copy, recorded in the manifest (a fresh clone has
    // no .env): a key for THAT app, never a new one. A record that names the
    // live app itself is ignored: a test key is never minted for it.
    let recorded = typeof manifest.testApp?.appId === 'string' && manifest.testApp.appId.trim() ? manifest.testApp.appId.trim() : null;
    if (recorded && recorded === manifest.deploy?.appId) {
      if (!options.json) log('  (For the AI: the test copy recorded in piezas.manifest.json (testApp) is the live app itself, so it was ignored; never point testApp at the live app.)');
      recorded = null;
    }
    let created = recorded
      ? { status: 201, data: { id: recorded, name: manifest.testApp.appName ?? name } }
      : await fetchJson(fetchFn, `${tenantPath}/partitions`, { ...http, method: 'POST', body: { name } });
    // From an AI run a taken name is never reused: the next free
    // "<name> (test 2)", "(test 3)" … is made instead.
    if (created.status === 409 && aiRunForOwner(options, env, root)) {
      for (let n = 2; n <= 5 && created.status === 409; n += 1) {
        created = await fetchJson(fetchFn, `${tenantPath}/partitions`, { ...http, method: 'POST', body: { name: `${baseName} (test ${n})` } });
      }
      if (created.status === 409) return { ok: false, status: 'name-taken', message: say(OWNER_TEXT.testCopyFailed) };
    }
    if (created.status === 201 && created.data?.id) {
      app = created.data;
    } else if (created.status === 409) {
      const listed = await fetchJson(fetchFn, `${tenantPath}/my-apps`, http);
      const slug = slugifyAppName(name);
      app = (Array.isArray(listed.data?.data) ? listed.data.data : []).find((p) => p?.slug === slug || p?.name === name);
      if (!app) return { ok: false, status: 'not-found', message: say(OWNER_TEXT.testCopyFailed) };
    } else if (created.status === 401) {
      return { ok: false, status: 'not-signed-in', message: say(OWNER_TEXT.testCopyNotSignedIn) };
    } else if (created.status === 403) {
      return { ok: false, status: 'not-allowed', message: say(OWNER_TEXT.testCopyNotAllowed) };
    } else {
      return { ok: false, status: `http-${created.status}`, message: say(OWNER_TEXT.testCopyFailed) };
    }
    const minted = await fetchJson(fetchFn, `${tenantPath}/api-keys`, {
      ...http, method: 'POST', body: { name, environment: 'test', partitionId: app.id },
    });
    if (recorded && [400, 403, 404].includes(minted.status)) {
      // The recorded test copy is gone (or not this account's): forget it and
      // make one as for a project with none recorded.
      try {
        const m = readManifestSafe(root);
        if (m?.testApp?.appId === recorded) {
          delete m.testApp;
          writeFileSync(manifestPath, `${JSON.stringify(m, null, 2)}\n`);
          return setupTestApp(projectDir, options);
        }
      } catch { /* fall through to the plain failure */ }
    }
    if (minted.status !== 201 || typeof minted.data?.key !== 'string' || !minted.data.key) {
      return { ok: false, status: `key-http-${minted.status}`, message: say(minted.status === 401 ? OWNER_TEXT.testCopyNotSignedIn : OWNER_TEXT.testCopyFailed) };
    }
    writeEnvVar(envPath, 'PIEZAS_TEST_API_KEY', minted.data.key);
    ensureTestUser(envPath, name);
    const sink = io.detailSink;
    io.detailSink = [];
    try { ensureGitignore(root); } finally { io.detailSink = sink; }
    try {
      const m = readManifestSafe(root);
      if (m) {
        m.testApp = { appId: app.id, appName: app.name ?? name };
        writeFileSync(manifestPath, `${JSON.stringify(m, null, 2)}\n`);
      }
    } catch { /* informational */ }
    writeSeedScript(root, parseDataModel(readScenarios(root).text));
    return { ok: true, status: 'created', appName: app.name ?? name, appId: app.id, message: say(OWNER_TEXT.testCopyMade(app.name ?? name)) };
  } catch {
    return { ok: false, status: 'offline', message: say(OWNER_TEXT.testCopyOffline) };
  }
}

// The test sign-in person: made-up email on example.test, a random password,
// both in .env (never printed). The seed script creates and activates them
// with the test copy's key, so sign-in checks need no real inbox.
function ensureTestUser(envPath, appName) {
  const current = existsSync(envPath) ? readFileSync(envPath, 'utf-8') : '';
  if (!/^\s*PIEZAS_TEST_USER_EMAIL\s*=/m.test(current)) {
    writeEnvVar(envPath, 'PIEZAS_TEST_USER_EMAIL', `tester@${slugifyAppName(appName) || 'app'}.example.test`);
  }
  if (!/^\s*PIEZAS_TEST_USER_PASSWORD\s*=/m.test(current)) {
    writeEnvVar(envPath, 'PIEZAS_TEST_USER_PASSWORD', `T${randomBytes(18).toString('base64url')}9!`);
  }
}

// parseDataModel — "## Data" (or Data Model / Records / Information) bullets
// like "- Contact: name, email, phone, status".
export function parseDataModel(specText) {
  const lines = blankComments(String(specText || '')).split(/\r?\n/);
  const sections = splitSections(lines);
  const section = ['data', 'data model', 'records', 'information', 'what the app keeps'].map((k) => sections.get(k)).find(Boolean);
  const kinds = [];
  for (const line of section?.lines ?? []) {
    const m = /^\s*[-*]\s*\**([A-Za-z][\w ]{0,40}?)\**\s*(?::|\(|—|-)\s*([^)]*)\)?\s*$/.exec(line.text);
    if (!m) continue;
    const fields = m[2].split(/,|;|\band\b/).map((f) => f.trim().replace(/\.$/, '')).filter((f) => /^[A-Za-z][\w ]{0,30}$/.test(f));
    kinds.push({ name: m[1].trim(), fields });
  }
  return kinds;
}

const PEOPLE = [['Avery', 'Example'], ['Jordan', 'Sample'], ['Riley', 'Placeholder']];

function camel(text) {
  const words = String(text).toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  return words.map((w, i) => (i ? w.charAt(0).toUpperCase() + w.slice(1) : w)).join('') || 'item';
}

function pluralAccessor(name) {
  const c = camel(name);
  if (/(s|x|z|ch|sh)$/.test(c)) return `${c}es`;
  if (/[^aeiou]y$/.test(c)) return `${c.slice(0, -1)}ies`;
  return `${c}s`;
}

export function syntheticValue(field, i) {
  const [first, last] = PEOPLE[i % PEOPLE.length];
  const f = field.toLowerCase();
  if (/e-?mail/.test(f)) return `${first.toLowerCase()}.${last.toLowerCase()}@example.test`;
  if (/phone|mobile|cell/.test(f)) return `+1 555 01${String(10 + i).padStart(2, '0')}`;
  if (/date|day|when|time|start|end|due|\bat\b/.test(f)) return `2030-01-${String(10 + i).padStart(2, '0')}T15:00:00Z`;
  if (/amount|price|total|cost|fee|rate|budget|balance/.test(f)) return 100 + i * 25;
  if (/status|stage|state/.test(f)) return 'active';
  if (/note|description|comment|details|message|summary/.test(f)) return `Made-up note ${i + 1} for testing.`;
  if (/address|street/.test(f)) return `${100 + i} Example Street`;
  if (/city|town/.test(f)) return 'Exampleton';
  if (/company|business|organi[sz]ation/.test(f)) return `${last} Test Co.`;
  if (/name|client|customer|person|contact|owner|guest/.test(f)) return `${first} ${last}`;
  if (/count|number|qty|quantity|seats|guests|size|party/.test(f)) return 2 + i;
  return `Sample ${field} ${i + 1}`;
}

export function seedScriptFromModel(model = []) {
  const blocks = model.map((kind) => {
    const fields = kind.fields.length ? kind.fields : ['name'];
    const titleField = fields.find((f) => /name|title|client|customer|person|contact/i.test(f)) ?? fields[0];
    const records = PEOPLE.map((_, i) => {
      const data = Object.fromEntries(fields.map((f) => [camel(f), syntheticValue(f, i)]));
      return `  await upsert(${JSON.stringify(pluralAccessor(kind.name))}, ${JSON.stringify(String(syntheticValue(titleField, i)))}, ${JSON.stringify(data)});`;
    });
    return `  // ${kind.name}: ${fields.join(', ')}\n${records.join('\n')}`;
  });
  return `// Made-up information for the app's checks. Piezas writes this file from the
// data your description lists; edit it freely. Deterministic (fixed names,
// dates and amounts) so a check gives the same result today and next year.
//
// It runs ONLY against the TEST copy of the app (PIEZAS_TEST_API_KEY, made by
// \`piezas test --setup\`), never the live app, and it is safe to run again:
// each record is created only if it is not there yet. Names and emails are
// invented (example.test addresses never receive mail).
//
// \`piezas test\` runs it before every check:  npx tsx scripts/seed.ts
import { Piezas } from '@piezas/sdk';

const apiKey = process.env.PIEZAS_TEST_API_KEY;
if (!apiKey) {
  console.error('No test copy of the app yet (PIEZAS_TEST_API_KEY is missing). Run: piezas test --setup');
  process.exit(1);
}
const piezas = new Piezas({ apiKey, apiBaseUrl: process.env.PIEZAS_API_URL });

// upsert creates a record by title only when it does not exist yet. The record
// kinds must be defined by the app (piezas.defineEntities) before this runs.
async function upsert(accessor: string, title: string, data: Record<string, unknown>) {
  const records = (piezas as unknown as Record<string, any>)[accessor];
  if (!records?.list || !records?.create) {
    console.warn(\`\${accessor}: not defined yet; run the app once (it defines its records), then seed again\`);
    return;
  }
  const found = await records.list({ search: title, limit: 10 });
  const items: any[] = Array.isArray(found) ? found : found?.data ?? found?.items ?? found?.records ?? [];
  if (items.some((r) => r?.title === title)) return;
  await records.create({ title, data });
}

// The test sign-in person: created and switched on directly with the test
// copy's key, so sign-up and sign-in checks never wait for an email.
async function testSignInUser() {
  const email = process.env.PIEZAS_TEST_USER_EMAIL;
  const password = process.env.PIEZAS_TEST_USER_PASSWORD;
  if (!email || !password) return;
  let user: any;
  try {
    ({ user } = await piezas.users.signUp({ email, password }));
  } catch {
    const listed: any = await piezas.users.listUsers({ email });
    user = (listed?.users ?? listed?.data ?? [])[0];
  }
  if (user?.id && user.status !== 'active') await piezas.users.updateUser(user.id, { status: 'active' });
}

export async function seed() {
  await testSignInUser();
${blocks.join('\n\n')}
}

seed().then(
  () => console.log('test information ready'),
  (error) => {
    console.error(error?.message ?? error);
    process.exit(1);
  },
);
`;
}

// writeSeedScript — writes scripts/seed.ts when it is missing or still the
// untouched starter (never over someone's own seed script).
export function writeSeedScript(root, model) {
  const path = join(root, 'scripts', 'seed.ts');
  if (existsSync(path)) {
    const current = readFileSync(path, 'utf-8');
    const starter = current.includes('TODO(you): create the fixtures') || current.startsWith("// Made-up information for the app's checks. Piezas writes this file");
    if (!starter) return false;
    const next = seedScriptFromModel(model);
    if (current === next) return false;
    writeFileSync(path, next);
    return true;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, seedScriptFromModel(model));
  return true;
}

// ===========================================================================
// The Report a problem button, added by the tool (not the AI)
// ===========================================================================

export const REPORT_ROUTE_CONTENT = `import { Piezas, createReportProblemRoute } from '@piezas/sdk';

// Added by Piezas: saves "Report a problem" reports in this app's own records.
// Keep it: whether the button shows is the owner's answer at each deploy.
const piezas = new Piezas({ apiKey: process.env.PIEZAS_API_KEY! });
export const { GET, POST } = createReportProblemRoute({ piezas });
`;

export const REPORT_MOUNT_CONTENT = `'use client';
import { mountReportProblem } from '@piezas/sdk/report-problem';

// Added by Piezas. Mounted when this file loads, outside React, so the button
// outlives a crash. Whether it shows is the owner's answer at each deploy.
if (typeof window !== 'undefined') mountReportProblem();

export function ReportProblem() {
  return null;
}
`;

function nextAppDir(root) {
  for (const dir of ['app', 'src/app']) {
    if (['layout.tsx', 'layout.jsx', 'layout.js', 'layout.ts'].some((f) => existsSync(join(root, dir, f)))) return dir;
  }
  return null;
}

function hasNext(root) {
  try {
    const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf-8'));
    return Boolean(pkg?.dependencies?.next || pkg?.devDependencies?.next);
  } catch {
    return false;
  }
}

function serverMode(root) {
  const mode = readManifestSafe(root)?.deploymentMode;
  return !mode || mode === 'next-bff' || mode === 'server-runtime';
}

function walkSource(root, visit) {
  const walk = (dir, depth) => {
    if (depth > 8) return;
    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      if (e.isSymbolicLink()) continue;
      const full = join(dir, e.name);
      if (e.isDirectory()) {
        if (!FINGERPRINT_SKIP_ANY_DEPTH.has(e.name) && e.name !== 'tests' && e.name !== 'e2e') walk(full, depth + 1);
      } else if (/\.(?:[cm]?[jt]sx?)$/.test(e.name)) {
        if (visit(full) === 'stop') return;
      }
    }
  };
  walk(root, 0);
}

// exportedComponents — the components a module exports, as an importer would
// use them: named exports ({ name }) and the default export ({ default: true,
// name: its own name if it has one }). Covers `export function X`,
// `export const X = () =>`, `export class X`, `export { X, Y as Z }`,
// `export default function X`, `export default X`, `export default () =>`
// and `export { X as default }`.
export function exportedComponents(source) {
  const text = stripComments(String(source || ''));
  const named = new Set();
  let def = null;
  for (const m of text.matchAll(/\bexport\s+(?:async\s+)?(?:function\s*\*?|const|let|var|class)\s+([A-Za-z_$][\w$]*)/g)) named.add(m[1]);
  for (const m of text.matchAll(/\bexport\s*\{([^}]*)\}(?!\s*from)/g)) {
    for (const part of m[1].split(',')) {
      const [local, exported] = part.trim().split(/\s+as\s+/).map((x) => x?.trim());
      if (!local) continue;
      if ((exported ?? local) === 'default') def = { default: true, name: local };
      else named.add(exported ?? local);
    }
  }
  const d = /\bexport\s+default\s+(?:async\s+)?(?:(?:function|class)\b\s*\*?\s*([A-Za-z_$][\w$]*)?|([A-Za-z_$][\w$]*)\s*;?\s*$|([A-Za-z_$][\w$]*)\s*(?:;|\n)|)/m.exec(text);
  if (d) {
    const name = d[1] ?? d[2] ?? d[3] ?? null;
    def = { default: true, name: name && !/^(?:async|function|class)$/.test(name) ? name : null };
  }
  return { named: [...named], default: def };
}

// importsOf — the names a file binds from imports whose path ends in `stem`
// (./report-problem, @/app/report-problem, ../report-problem/index ...).
function importsOf(text, stem) {
  const found = { default: [], named: new Map(), namespace: [] };
  for (const m of text.matchAll(/\bimport\s+([^'";]*?)\s+from\s+['"]([^'"]+)['"]/g)) {
    const spec = m[2].replace(/\.[cm]?[jt]sx?$/, '').replace(/\/index$/, '');
    if (spec.split('/').pop() !== stem) continue;
    let clause = m[1].trim();
    const ns = /\*\s+as\s+([A-Za-z_$][\w$]*)/.exec(clause);
    if (ns) found.namespace.push(ns[1]);
    const braces = /\{([^}]*)\}/.exec(clause);
    if (braces) {
      for (const part of braces[1].split(',')) {
        const [imported, local] = part.trim().replace(/^type\s+/, '').split(/\s+as\s+/).map((x) => x?.trim());
        if (imported) found.named.set(imported, local ?? imported);
      }
      clause = clause.replace(braces[0], '');
    }
    const def = /^([A-Za-z_$][\w$]*)/.exec(clause.replace(/\*\s+as\s+[A-Za-z_$][\w$]*/, '').replace(/^,|,$/g, '').trim());
    if (def && def[1] !== 'type') found.default.push(def[1]);
  }
  return found;
}

// renders — does `text` render one of the mount file's components?
function rendersComponent(text, stem, exported) {
  const imports = importsOf(text, stem);
  const locals = [];
  if (exported.default) locals.push(...imports.default);
  for (const name of exported.named) if (imports.named.has(name)) locals.push(imports.named.get(name));
  for (const ns of imports.namespace) for (const name of exported.named) locals.push(`${ns}.${name}`);
  if (exported.default) for (const ns of imports.namespace) locals.push(`${ns}.default`);
  return locals.some((local) => new RegExp(`<${local.replace(/[.$]/g, '\\$&')}[\\s/>]`).test(text));
}

// reportButtonStatus — for a Next app-router server app: is the route there,
// and is the button mounted somewhere in the app? Other apps: not applicable.
export function reportButtonStatus(projectDir) {
  const root = resolve(projectDir);
  const appDir = nextAppDir(root);
  if (!appDir || !hasNext(root) || !serverMode(root)) return { applicable: false, ok: true };
  const route = ['route.ts', 'route.js', 'route.tsx', 'route.mjs'].map((f) => `${appDir}/api/piezas/report/${f}`).find((rel) => existsSync(join(root, rel)));
  let mountFile = null;
  let mounted = false;
  let component = null;
  const top = join(root, appDir.split('/')[0]);
  walkSource(top, (full) => {
    const text = readFileSync(full, 'utf-8');
    if (/\bmountReportProblem\s*\(/.test(text)) mountFile = full;
    return undefined;
  });
  if (mountFile) {
    const exported = exportedComponents(readFileSync(mountFile, 'utf-8'));
    const firstNamed = exported.named.find((n) => /^[A-Z]/.test(n));
    component = firstNamed ? { name: firstNamed, default: false }
      : exported.default ? { name: exported.default.name && /^[A-Z]/.test(exported.default.name) ? exported.default.name : 'ReportProblem', default: true } : null;
    const mountRel = toPosix(relative(root, mountFile));
    const stem = basename(mountFile).replace(/\.[cm]?[jt]sx?$/, '');
    const importStem = stem === 'index' ? basename(dirname(mountFile)) : stem;
    walkSource(top, (full) => {
      if (full === mountFile) return undefined;
      const text = readFileSync(full, 'utf-8');
      if (rendersComponent(text, importStem, exported) || /\bmountReportProblem\s*\(/.test(text)) {
        mounted = true;
        return 'stop';
      }
      return undefined;
    });
    // A layout that calls mountReportProblem directly counts too.
    if (!mounted && /layout\.[cm]?[jt]sx?$/.test(mountRel)) mounted = true;
  }
  return {
    applicable: true,
    ok: Boolean(route) && mounted,
    route: route ?? null,
    mountFile: mountFile ? toPosix(relative(root, mountFile)) : null,
    component,
    mounted,
    appDir,
  };
}

// wireLayout — add <ReportProblem /> (or the mount file's own component) just
// before </body> in the root layout, only when that can be done safely
// (exactly one <body> and one </body>).
export function wireLayout(layoutText, importPath, component = { name: 'ReportProblem', default: false }) {
  const name = component?.name || 'ReportProblem';
  if (new RegExp(`<${name}[\\s/>]`).test(layoutText) && layoutText.includes(importPath)) return { ok: true, text: layoutText, changed: false };
  const opens = layoutText.match(/<body[\s>]/g) ?? [];
  const closes = layoutText.match(/<\/body>/g) ?? [];
  if (opens.length !== 1 || closes.length !== 1) return { ok: false, text: layoutText, changed: false };
  // The layout already uses that name for something else: do not guess.
  if (new RegExp(`\\b${name}\\b`).test(layoutText)) return { ok: false, text: layoutText, changed: false };
  const indented = /\n([ \t]*)<\/body>/.exec(layoutText);
  let text = indented
    ? layoutText.replace(/\n([ \t]*)<\/body>/, (_, indent) => `\n${indent}  <${name} />\n${indent}</body>`)
    : layoutText.replace(/<\/body>/, `<${name} /></body>`);
  const importLine = component?.default ? `import ${name} from '${importPath}';` : `import { ${name} } from '${importPath}';`;
  const lines = text.split('\n');
  let lastEnd = -1;
  let inImport = false;
  lines.forEach((line, i) => {
    if (/^import\b/.test(line)) inImport = true;
    if (inImport && (/\bfrom\s+['"][^'"]+['"]/.test(line) || /^import\s+['"][^'"]+['"]/.test(line))) {
      lastEnd = i;
      inImport = false;
    }
  });
  if (lastEnd >= 0) {
    lines.splice(lastEnd + 1, 0, importLine);
  } else {
    const directive = lines.findIndex((l) => /^\s*['"]use (?:client|server)['"];?\s*$/.test(l));
    lines.splice(directive >= 0 ? directive + 1 : 0, 0, importLine);
  }
  text = lines.join('\n');
  return { ok: true, text, changed: true };
}

export const REPORT_BUTTON_TODO = 'report-button-todo.md';

// scaffoldReportButton — idempotent. Writes the route and the button file and
// wires the button into the root layout when that is safe (also for a button
// file the app already has); otherwise leaves an AI-facing note in
// .piezas/report-button-todo.md (doctor PZ027 repeats it). Agrees with
// reportButtonStatus: ok here means the status check is ok too.
export function scaffoldReportButton(projectDir, options = {}) {
  const root = resolve(projectDir);
  const appDir = nextAppDir(root);
  if (!appDir || !hasNext(root) || !serverMode(root)) return { applicable: false, created: [], wired: false };
  const before = reportButtonStatus(root);
  if (before.ok) {
    rmSync(join(root, STATE_DIR, REPORT_BUTTON_TODO), { force: true });
    return { applicable: true, created: [], wired: true, ok: true, mountFile: before.mountFile };
  }
  const created = [];
  if (!before.route) {
    const rel = `${appDir}/api/piezas/report/route.ts`;
    mkdirSync(join(root, dirname(rel)), { recursive: true });
    writeFileSync(join(root, rel), REPORT_ROUTE_CONTENT);
    created.push(rel);
  }
  let mountRel = before.mountFile;
  let component = before.component;
  if (!mountRel) {
    mountRel = `${appDir}/report-problem.tsx`;
    if (!existsSync(join(root, mountRel))) {
      writeFileSync(join(root, mountRel), REPORT_MOUNT_CONTENT);
      created.push(mountRel);
    }
    component = { name: 'ReportProblem', default: false };
  }
  let after = reportButtonStatus(root);
  let wired = after.mounted;
  const layoutRel = ['layout.tsx', 'layout.jsx', 'layout.js', 'layout.ts'].map((f) => `${appDir}/${f}`).find((rel) => existsSync(join(root, rel)));
  let reason = null;
  if (!wired && !component) {
    reason = `${mountRel} starts the button but exports no component to render`;
  } else if (!wired && !layoutRel) {
    reason = 'there is no root layout';
  } else if (!wired) {
    let importPath = toPosix(relative(dirname(join(root, layoutRel)), join(root, mountRel))).replace(/\.[cm]?[jt]sx?$/, '').replace(/\/index$/, '');
    if (!importPath.startsWith('.')) importPath = `./${importPath}`;
    const layoutText = readFileSync(join(root, layoutRel), 'utf-8');
    const result = wireLayout(layoutText, importPath, component);
    if (result.ok && result.changed) {
      writeFileSync(join(root, layoutRel), result.text);
      created.push(`${layoutRel} (button added)`);
    }
    after = reportButtonStatus(root);
    wired = after.mounted;
    if (!wired) reason = `the root layout (${layoutRel}) could not be edited safely`;
  }
  const todo = join(root, STATE_DIR, REPORT_BUTTON_TODO);
  const render = component ? `<${component.name} />` : 'a component that returns null';
  const instruction = component
    ? `Render \`${render}\` (${component.default ? 'the default export' : `export ${component.name}`} of ${mountRel}) once inside <body> of the root layout${layoutRel ? ` (${layoutRel})` : ''}`
    : `Export a component that returns null from ${mountRel}, then render it once inside <body> of the root layout${layoutRel ? ` (${layoutRel})` : ''}`;
  if (!wired) {
    mkdirSync(join(root, STATE_DIR), { recursive: true });
    writeFileSync(todo, `# For the AI: finish adding the Report a problem button\n\n`
      + `The button file is ${mountRel}, but it is not shown on the app's pages: ${reason}.\n`
      + `${instruction}, then delete this file.\n`
      + 'Never remove the button: whether it shows is the owner\'s answer at each deploy.\n');
  } else {
    rmSync(todo, { force: true });
  }
  if (created.length && !options.quiet) log(`  ${OWNER_TEXT.reportButtonAdded}`);
  const ok = wired && Boolean(after.route);
  return { applicable: true, created, wired, ok, mountFile: mountRel, layout: layoutRel ?? null, component, ...(wired ? {} : { reason, instruction, todo: `${STATE_DIR}/${REPORT_BUTTON_TODO}` }) };
}

// PZ027 — doctor's view of the same thing.
export function scanReportButton(projectDir, findings, addFinding) {
  const status = reportButtonStatus(projectDir);
  if (!status.applicable || status.ok) return;
  const missing = [!status.route ? `the route (${status.appDir}/api/piezas/report/route.ts)` : null, !status.mounted ? 'the button mounted in the root layout (<ReportProblem />)' : null].filter(Boolean);
  addFinding(
    findings,
    'error',
    'PZ027',
    `This server app has no Report a problem button: missing ${missing.join(' and ')}. Run \`npx piezas report-button add\` `
      + '(it writes both and wires the layout when it safely can), then rebuild. Never remove it: on/off is the owner\'s answer at each deploy.',
    status.route ?? `${status.appDir}/api/piezas/report/route.ts`,
  );
}
